  double sum=0; long cnt=0;
  for(int y=0;y<h;y++) for(int x=1;x<w;x++) for(int c=0;c<3;c++){ sum += abs(px[(y*w+x)*4+c]-px[(y*w+x-1)*4+c]); cnt++; }
  printf("avg horiz diff = %.2f\n", sum/cnt);
  sum=0;cnt=0;
  for(int y=1;y<h;y++) for(int x=0;x<w;x++) for(int c=0;c<3;c++){ sum += abs(px[(y*w+x)*4+c]-px[((y-1)*w+x)*4+c]); cnt++; }
  printf("avg vert diff = %.2f\n", sum/cnt);
  FILE* f=fopen("/tmp/dec.ppm","wb"); fprintf(f,"P6\n%d %d 255\n",w,h); fwrite(px,1,(size_t)w*h*3,f); fclose(f);
  printf("wrote /tmp/dec.ppm\n");
  return 0;
}
