import struct
for f in ('in/g1.gif','ogf/g1q50.gif','ogf/g1ll.gif'):
    d=open(f,'rb').read()
    print("==",f,len(d))
    i=6
    gct=None
    if d[10]&0x80:
        gct=2**(d[10]&7+1)
    pos=13
    if d[10]&0x80: pos+=3*2**(1+(d[10]&7))
    nframes=0; netsc=0
    while pos<len(d):
        b=d[pos]
        if b==0x21:
            lbl=d[pos+1]
            if lbl==0xF9:
                sz=d[pos+2]; flags=d[pos+4]
                print("  GCE flags=%02x delay=%d transp_idx=%d"%(flags, struct.unpack('<H',d[pos+5:pos+7])[0], d[pos+7]) if sz>=8 else "  GCE")
                pos+=2+sz
            elif lbl==0xFF:
                sz=d[pos+2]; print("  AppExt",d[pos+3:pos+3+sz][:11]); pos+=2+sz
            elif lbl==0xFE:
                sz=d[pos+2]; print("  Comment",d[pos+3:pos+3+sz][:40]); pos+=2+sz
            else:
                sz=d[pos+2]; print("  Ext",hex(lbl),"len",sz); pos+=2+sz
        elif b==0x2C:
            l,t=struct.unpack('<HH',d[pos+1:pos+5]); w,h=struct.unpack('<HH',d[pos+5:pos+9]); fl=d[pos+9]
            print("  IMG l=%d t=%d w=%d h=%d flags=%02x localct=%d interlace=%d szct=%d"%(l,t,w,h,fl,1 if fl&0x80 else 0, 1 if fl&0x40 else 0, 2**(1+(fl&7)) if fl&0x80 else 0))
            pos+=10
            if fl&0x80: pos+=3*2**(1+(fl&7))
            # LZW data blocks
            n=0
            while True:
                sz=d[pos]; pos+=1+sz; n+=sz
                if sz==0: break
            nframes+=1
        elif b==0x3B:
            print("  TRAILER @%d"%pos); pos+=1
        else:
            print("  unknown byte %02x @%d"%(b,pos)); break
    print("  frames=%d"%nframes)
EOF"}

