                sz=d[pos]; app=d[pos+1:pos+1+sz]; pos+=1+sz
                subs=b''
                while d[pos]!=0: sz=d[pos]; subs+=d[pos+1:pos+1+sz]; pos+=1+sz
                pos+=1
                if verbose: print("  AppExt %s %s"%(app,subs.hex()))
            elif lbl==0xF9:
                sz=d[pos]; pay=d[pos+1:pos+1+sz]; pos+=1+sz
                while d[pos]!=0: pos+=1+d[pos]
                pos+=1
                frames.append(('gce',pay))
                if verbose: print("  GCE flags=%02x delay=%d transp=%d"%(pay[0],struct.unpack('<H',pay[1:3])[0],pay[3]))
            else:
                sz=d[pos]; pay=d[pos+1:pos+1+sz]; pos+=1+sz
                while d[pos]!=0: pos+=1+d[pos]
                pos+=1
                if verbose: print("  Ext %02x len=%d %s"%(lbl,sz,pay[:20]))
        elif b==0x2C:
            l,t=struct.unpack('<HH',d[pos+1:pos+5]); w,h=struct.unpack('<HH',d[pos+5:pos+9]); fl=d[pos+9]
            pos+=10
            if fl&0x80: pos+=3*2**(1+(fl&7))
            n=0
            while d[pos]!=0: sz=d[pos]; pos+=1+sz; n+=sz
            pos+=1
            frames.append(('img',l,t,w,h,fl,n))
            if verbose: print("  IMG l=%d t=%d w=%d h=%d flags=%02x localct=%s interlace=%d lzw=%d"%(l,t,w,h,fl,'yes(%d)'%(2**(1+(fl&7))) if fl&0x80 else 'no',1 if fl&0x40 else 0,n))
        elif b==0x3B:
            if verbose: print("  TRAILER @%d"%pos)
            pos+=1
        else:
            print("  UNKNOWN %02x @%d"%(b,pos)); break
    print("  blocks=%d"%len(frames))
for f in sys.argv[1:]: parse(f)
