}

var formatValues = []string{"jpeg", "png", "gif", "webp", "tiff", "original"}
var subsamplingValues = []string{"4:4:4", "4:2:2", "4:2:0", "4:1:1", "auto"}
var overwriteValues = []string{"all", "never", "bigger"}

func findOpt(long string) *optSpec {
	for i := range opts {
		if opts[i].long == long {
			return &opts[i]
		}
	}
	return nil
}

func findShort(c byte) *optSpec {
	for i := range opts {
		if opts[i].short != "" && opts[i].short[0] == c {
			return &opts[i]
		}
	}
	return nil
}

// displayName renders the option as clap does in error messages
func displayName(o *optSpec) string {
	if o.val != "" {
		return "--" + o.long + " <" + o.val + ">"
	}
	return "--" + o.long
}

func usageArgName(o *optSpec) string {
	if o.val != "" {
		return "--" + o.long + " <" + o.val + ">"
	}
	return "--" + o.long
}

var groupNames = []string{
	1: "<--quality <QUALITY>|--lossless|--max-size <MAX_SIZE>>",
	2: "<--output <OUTPUT>|--same-folder-as-input>",
}

type usedArg struct {
	spec *optSpec
	// order in which it appeared on the command line
}

type cliParser struct {
	args     []string
	pos      int
	prog     string
	cfg      *config
	used     []*optSpec // options used, in command line order
	files    []string
	sawFiles bool
}

func (p *cliParser) markUsed(o *optSpec) {
	for _, u := range p.used {
		if u == o {
			return
		}
	}
	p.used = append(p.used, o)
}

func (p *cliParser) errExit(msg string) {
	fmt.Fprintln(os.Stderr, msg)
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
	os.Exit(2)
}

// fullUsage renders the complete usage string
func (p *cliParser) fullUsage() string {
	return "Usage: " + p.prog + " [OPTIONS] " + groupNames[1] + " " + groupNames[2] + " [FILES]..."
}

// smartUsage renders the usage from the used args
func (p *cliParser) smartUsage(extra *optSpec, filesRequired bool) string {
	parts := []string{}
	seen := map[*optSpec]bool{}
	for _, u := range p.used {
		if u.group == 0 && !seen[u] {
			parts = append(parts, usageArgName(u))
			seen[u] = true
		}
	}
	if extra != nil && extra.group == 0 && !seen[extra] {
		parts = append(parts, usageArgName(extra))
		seen[extra] = true
	}
	parts = append(parts, groupNames[1], groupNames[2])
	files := "[FILES]..."
	if filesRequired {
		files = "<FILES>..."
	}
	parts = append(parts, files)
	return "Usage: " + p.prog + " " + strings.Join(parts, " ")
}

func (p *cliParser) helpError() {
	fmt.Println(strings.ReplaceAll(helpLong, "Usage: executable ", "Usage: "+p.prog+" "))
	os.Exit(0)
}

func (p *cliParser) shortHelpError() {
	fmt.Println(strings.ReplaceAll(helpShort, "Usage: executable ", "Usage: "+p.prog+" "))
	os.Exit(0)
}

func (p *cliParser) versionError() {
	fmt.Println("caesiumclt 1.3.0")
	os.Exit(0)
}

func invalidValue(arg, val, msg string) {
	p := "error: invalid value '" + val + "' for '" + arg + "'"
	if msg != "" {
		p += ": " + msg
	}
	fmt.Fprintln(os.Stderr, p)
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
	os.Exit(2)
}

func invalidValuePossible(arg, val string, possible []string, tip string) {
	fmt.Fprintln(os.Stderr, "error: invalid value '"+val+"' for '"+arg+"'")
	fmt.Fprintln(os.Stderr, "  [possible values: "+strings.Join(possible, ", ")+"]")
	if tip != "" {
		fmt.Fprintln(os.Stderr)
		fmt.Fprintln(os.Stderr, "  tip: a similar value exists: '"+tip+"'")
	}
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
	os.Exit(2)
}

func missingValue(arg string, possible []string) {
	fmt.Fprintln(os.Stderr, "error: a value is required for '"+arg+"' but none was supplied")
	if possible != nil {
		fmt.Fprintln(os.Stderr, "  [possible values: "+strings.Join(possible, ", ")+"]")
	}
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
	os.Exit(2)
}

func unexpectedArg(arg, tip string, usage string) {
	fmt.Fprintln(os.Stderr, "error: unexpected argument '"+arg+"' found")
	if tip != "" {
		fmt.Fprintln(os.Stderr)
		fmt.Fprintln(os.Stderr, "  tip: "+tip)
	}
	if usage != "" {
		fmt.Fprintln(os.Stderr)
		fmt.Fprintln(os.Stderr, usage)
	}
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
	os.Exit(2)
}

func unexpectedValue(val, arg string, usage string) {
	fmt.Fprintln(os.Stderr, "error: unexpected value '"+val+"' for '"+arg+"' found; no more were expected")
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, usage)
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
	os.Exit(2)
}

func (p *cliParser) requiredError(missing []string) {
	fmt.Fprintln(os.Stderr, "error: the following required arguments were not provided:")
	for _, m := range missing {
		fmt.Fprintln(os.Stderr, "  "+m)
	}
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, p.smartUsage(nil, true))
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
	os.Exit(2)
}

func (p *cliParser) conflictError(arg *optSpec, with []*optSpec) {
	if len(with) == 1 {
		fmt.Fprintln(os.Stderr, "error: the argument '"+displayName(arg)+"' cannot be used with '"+displayName(with[0])+"'")
	} else {
		fmt.Fprintln(os.Stderr, "error: the argument '"+displayName(arg)+"' cannot be used with:")
		for _, w := range with {
			fmt.Fprintln(os.Stderr, "  "+usageArgName(w))
		}
	}
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, p.smartUsage(nil, p.sawFiles))
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
	os.Exit(2)
}

func (p *cliParser) duplicateError(arg *optSpec) {
	fmt.Fprintln(os.Stderr, "error: the argument '"+displayName(arg)+"' cannot be used multiple times")
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, p.fullUsage())
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
	os.Exit(2)
}

// jaroWinkler similarity, as used by clap for suggestions
func jaroWinkler(a, b string) float64 {
	if a == b {
		return 1.0
	}
	la, lb := len(a), len(b)
	if la == 0 || lb == 0 {
		return 0.0
	}
	var matchWindow int
	if la > lb {
		matchWindow = la/2 - 1
	} else {
		matchWindow = lb/2 - 1
	}
	if matchWindow < 0 {
		matchWindow = 0
	}
	aMatched := make([]bool, la)
	bMatched := make([]bool, lb)
	matches := 0
	for i := 0; i < la; i++ {
		start := i - matchWindow
		if start < 0 {
			start = 0
		}
		end := i + matchWindow + 1
		if end > lb {
			end = lb
		}
		for j := start; j < end; j++ {
			if bMatched[j] || a[i] != b[j] {
				continue
			}
			aMatched[i] = true
			bMatched[j] = true
			matches++
			break
		}
	}
	if matches == 0 {
		return 0.0
	}
	transpositions := 0
	k := 0
	for i := 0; i < la; i++ {
		if !aMatched[i] {
			continue
		}
		for !bMatched[k] {
			k++
		}
		if a[i] != b[k] {
			transpositions++
		}
		k++
	}
	transpositions /= 2
	jaro := (float64(matches)/float64(la) + float64(matches)/float64(lb) +
		(float64(matches)-float64(transpositions))/float64(matches)) / 3.0
	// Winkler prefix boost
	var prefix int
	maxPrefix := 4
	if la < maxPrefix {
		maxPrefix = la
	}
	if lb < maxPrefix {
		maxPrefix = lb
	}
	for i := 0; i < maxPrefix; i++ {
		if a[i] == b[i] {
			prefix++
		} else {
			break
		}
	}
	if jaro < 0.7 {
		return jaro
	}
	return jaro + 0.1*float64(prefix)*(1.0-jaro)
}

func didYouMean(v string, candidates []string) []string {
	var out []string
	scores := map[string]float64{}
	for _, c := range candidates {
		if s := jaroWinkler(v, c); s > 0.8 {
			out = append(out, c)
			scores[c] = s
		}
	}
	// sort by descending confidence, then by original order
	for i := 0; i < len(out); i++ {
		for j := i + 1; j < len(out); j++ {
			if scores[out[j]] > scores[out[i]] {
				out[i], out[j] = out[j], out[i]
			}
		}
	}
	return out
}

// parseIntU8 style parse used by --quality/--verbose/--png-opt-level
func parseCustomNum(s string) (uint64, bool) {
	if s == "" {
		return 0, false
	}
	v, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		return 0, false
	}
	return v, true
}

func (p *cliParser) setLong(o *optSpec, val string, inline bool) {
	cfg := p.cfg
	switch o.long {
	case "quality":
		v, ok := parseCustomNum(val)
		if !ok {
			invalidValue(displayName(o), val, "'"+val+"' is not a valid number")
		}
		if v > 100 {
			invalidValue(displayName(o), val, "Quality must be between 0 and 100, but got "+strconv.FormatUint(v, 10))
		}
		cfg.quality = uint32(v)
		cfg.hasQuality = true
	case "lossless":
		cfg.lossless = true
	case "max-size":
		n, err := parseByteSize(val)
		if err != "" {
			invalidValue(displayName(o), val, "Invalid size format: "+err)
		}
		cfg.maxSize = n
		cfg.hasMaxSize = true
	case "width":
		cfg.width = p.parseU32(o, val)
		cfg.hasWidth = true
	case "height":
		cfg.height = p.parseU32(o, val)
		cfg.hasHeight = true
	case "long-edge":
		cfg.longEdge = p.parseU32(o, val)
		cfg.hasLongEdge = true
	case "short-edge":
		cfg.shortEdge = p.parseU32(o, val)
		cfg.hasShortEdge = true
	case "no-upscale":
		cfg.noUpscale = true
	case "output":
		if val == "" {
			missingValue(displayName(o), nil)
		}
		cfg.output = val
		cfg.hasOutput = true
	case "same-folder-as-input":
		cfg.sameFolder = true
	case "format":
		if val == "" {
			missingValue(displayName(o), formatValues)
		}
		if !inList(formatValues, val) {
			tip := ""
			if c := didYouMean(val, formatValues); len(c) > 0 {
				tip = c[0]
			}
			invalidValuePossible(displayName(o), val, formatValues, tip)
		}
		cfg.format = val
	case "png-opt-level":
		v, ok := parseU8(val)
		if !ok {
			invalidValue(displayName(o), val, "'"+val+"' is not a valid number")
		}
		if v > 6 {
			invalidValue(displayName(o), val, "PNG optimization level must be between 0 and 6, but got "+strconv.Itoa(int(v)))
		}
		cfg.pngOptLevel = int(v)
	case "jpeg-chroma-subsampling":
		if val == "" {
			missingValue(displayName(o), subsamplingValues)
		}
		if !inList(subsamplingValues, val) {
			tip := ""
			if c := didYouMean(val, subsamplingValues); len(c) > 0 {
				tip = c[0]
			}
			invalidValuePossible(displayName(o), val, subsamplingValues, tip)
		}
		cfg.subsampling = val
	case "jpeg-baseline":
		cfg.jpegBaseline = true
	case "zopfli":
		cfg.zopfli = true
	case "exif":
		cfg.exif = true
	case "keep-dates":
		cfg.keepDates = true
	case "strip-icc":
		cfg.stripICC = true
	case "suffix":
		cfg.suffix = val
		cfg.hasSuffix = true
	case "recursive":
		cfg.recursive = true
	case "keep-structure":
		cfg.keepStructure = true
	case "dry-run":
		cfg.dryRun = true
	case "threads":
		cfg.threads = p.parseUsize(o, val)
	case "overwrite":
		if val == "" {
			missingValue(displayName(o), overwriteValues)
		}
		if !inList(overwriteValues, val) {
			tip := ""
			if c := didYouMean(val, overwriteValues); len(c) > 0 {
				tip = c[0]
			}
			invalidValuePossible(displayName(o), val, overwriteValues, tip)
		}
		cfg.overwrite = val
	case "min-savings":
		ms, err := parseMinSavings(val)
		if err != "" {
			invalidValue(displayName(o), val, err)
		}
		cfg.minSavings = ms
	case "quiet":
		cfg.quiet = true
	case "verbose":
		v, ok := parseU8(val)
		if !ok {
			invalidValue(displayName(o), val, "'"+val+"' is not a valid number")
		}
		if v > 3 {
			invalidValue(displayName(o), val, "Verbosity must be between 0 and 3, but got "+strconv.Itoa(int(v)))
		}
		cfg.verbose = int(v)
	}
}

func inList(list []string, v string) bool {
	for _, x := range list {
		if x == v {
			return true
		}
	}
	return false
}

func parseU8(s string) (uint8, bool) {
	v, ok := parseCustomNum(s)
	if !ok || v > 255 {
		return 0, false
	}
	return uint8(v), true
}

func stdIntErr(s string, bits int) string {
	// reproduce the std numeric parse error messages
	if s == "" {
		return "cannot parse integer from empty string"
	}
	_, err := strconv.ParseUint(s, 10, bits)
	if err == nil {
		return ""
	}
	msg := err.Error()
	// Go's messages differ from Rust's; map them
	if strings.Contains(msg, "value out of range") {
		return "number too large to fit in target type"
	}
	return "invalid digit found in string"
}

func (p *cliParser) parseU32(o *optSpec, val string) uint32 {
	if msg := stdIntErr(val, 32); msg != "" {
		invalidValue(displayName(o), val, msg)
	}
	v, _ := strconv.ParseUint(val, 10, 64)
	if v > 4294967295 {
		invalidValue(displayName(o), val, strconv.FormatUint(v, 10)+" is not in 0..=4294967295")
	}
	return uint32(v)
}

func (p *cliParser) parseUsize(o *optSpec, val string) uint64 {
	if msg := stdIntErr(val, 64); msg != "" {
		invalidValue(displayName(o), val, msg)
	}
	v, _ := strconv.ParseUint(val, 10, 64)
	return v
}

func (p *cliParser) unknownFlag(arg string, inline string) {
	// build the list of candidate long flags
	var longs []string
	for i := range opts {
		longs = append(longs, "--"+opts[i].long)
	}
	sugg := didYouMean(arg, longs)
	var extra *optSpec
	if len(sugg) > 0 {
		name := strings.TrimPrefix(sugg[0], "--")
		extra = findOpt(name)
	}
	tip := "to pass '" + arg + "' as a value, use '-- " + arg + "'"
	if len(sugg) > 0 {
		tip = "a similar argument exists: '" + sugg[0] + "'"
		unexpectedArg(arg, tip, p.smartUsage(extra, p.sawFiles))
	}
	unexpectedArg(arg, tip, p.fullUsage())
}

// Parse processes the command line
func parseArgs(argv []string) (*config, []string) {
	cfg := newConfig()
	if len(argv) == 0 {
		prog := "caesiumclt"
		if len(os.Args) > 0 {
			prog = filepath.Base(os.Args[0])
		}
		missing := []string{groupNames[1], groupNames[2]}
		fmt.Fprintln(os.Stderr, "error: the following required arguments were not provided:")
		for _, m := range missing {
			fmt.Fprintln(os.Stderr, "  "+m)
		}
		fmt.Fprintln(os.Stderr)
		fmt.Fprintln(os.Stderr, "Usage: "+prog+" "+groupNames[1]+" "+groupNames[2]+" <FILES>...")
		fmt.Fprintln(os.Stderr)
		fmt.Fprintln(os.Stderr, "For more information, try '--help'.")
		os.Exit(2)
	}
	p := &cliParser{prog: filepath.Base(argv[0]), cfg: cfg}
	p.args = argv[1:]
	i := 0
	for i < len(p.args) {
		a := p.args[i]
		i++
		switch {
		case a == "--":
			for ; i < len(p.args); i++ {
				p.files = append(p.files, p.args[i])
			}
			p.sawFiles = len(p.files) > 0
		case strings.HasPrefix(a, "--"):
			name := a[2:]
			val := ""
			inline := false
			if eq := strings.IndexByte(name, '='); eq >= 0 {
				val = name[eq+1:]
				name = name[:eq]
				inline = true
			}
			if name == "" {
				p.unknownFlag(a, "")
			}
			o := findOpt(name)
			if o == nil {
				p.unknownFlag("--"+name, val)
			}
			if o.long == "help" {
				p.helpError()
			}
			if o.long == "version" {
				p.versionError()
			}
			if o.val == "" {
				if inline {
					p.markUsed(o)
					unexpectedValue(val, "--"+o.long, p.smartUsage(o, p.sawFiles))
				}
				p.applyFlag(o)
				continue
			}
			if inline {
				p.markUsed(o)
				p.setLong(o, val, true)
				continue
			}
			// value from next arg
			if i >= len(p.args) {
				p.markUsed(o)
				missingValue(displayName(o), possibleValues(o))
			}
			next := p.args[i]
			if strings.HasPrefix(next, "-") && len(next) > 1 {
				// known flag => missing value; unknown => unexpected argument
				if strings.HasPrefix(next, "--") {
					n := strings.TrimPrefix(next, "--")
					if eq := strings.IndexByte(n, '='); eq >= 0 {
						n = n[:eq]
					}
					if findOpt(n) != nil || n == "help" || n == "version" {
						p.markUsed(o)
						missingValue(displayName(o), possibleValues(o))
					}
					p.unknownFlag(next, "")
				} else {
					// short cluster
					c := next[1]
					if findShort(c) != nil || c == 'h' || c == 'V' {
						p.markUsed(o)
						missingValue(displayName(o), possibleValues(o))
					}
					p.unexpectedShort(next)
				}
			}
			i++
			p.markUsed(o)
			p.setLong(o, next, false)
		case strings.HasPrefix(a, "-") && len(a) > 1:
			// short option cluster
			body := a[1:]
			j := 0
			for j < len(body) {
				c := body[j]
				o := findShort(c)
				if o == nil {
					if c == 'h' {
						p.shortHelpError()
					}
					if c == 'V' {
						p.versionError()
					}
					p.unexpectedShort(a)
				}
				j++
				if o.val == "" {
					if o.long == "help" {
						p.shortHelpError()
					}
					if o.long == "version" {
						p.versionError()
					}
					p.applyFlag(o)
					continue
				}
				rest := body[j:]
				if len(rest) > 0 {
					if rest[0] == '=' {
						rest = rest[1:]
					}
					p.markUsed(o)
					p.setLong(o, rest, true)
					j = len(body)
					continue
				}
				if i >= len(p.args) {
					p.markUsed(o)
					missingValue(displayName(o), possibleValues(o))
				}
				next := p.args[i]
				if strings.HasPrefix(next, "-") && len(next) > 1 {
					if strings.HasPrefix(next, "--") {
						n := strings.TrimPrefix(next, "--")
						if eq := strings.IndexByte(n, '='); eq >= 0 {
							n = n[:eq]
						}
						if findOpt(n) != nil {
							p.markUsed(o)
							missingValue(displayName(o), possibleValues(o))
						}
						p.unknownFlag(next, "")
					} else {
						cc := next[1]
						if findShort(cc) != nil {
							p.markUsed(o)
							missingValue(displayName(o), possibleValues(o))
						}
						p.unexpectedShort(next)
					}
				}
				i++
				p.markUsed(o)
				p.setLong(o, next, false)
				j = len(body)
			}
		default:
			p.files = append(p.files, a)
			p.sawFiles = true
		}
	}
	// validate
	p.validate()
	return cfg, p.files
}

func possibleValues(o *optSpec) []string {
	switch o.long {
	case "format":
		return formatValues
	case "overwrite":
		return overwriteValues
	case "jpeg-chroma-subsampling":
		return subsamplingValues
	}
	return nil
}

func (p *cliParser) unexpectedShort(a string) {
	s := "-" + a[1:2]
	unexpectedArg(s, "to pass '"+s+"' as a value, use '-- "+s+"'", p.fullUsage())
}

func (p *cliParser) applyFlag(o *optSpec) {
	if p.seen[o.long] {
		p.duplicateError(o)
	}
	p.seen[o.long] = true
	p.markUsed(o)
	p.setLong(o, "", false)
}
GOEOF
echo written; wc -l src/cli.go"}

