{"command": "cat > src/size.go <<'GOEOF'
package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

// formatSize renders a byte count the way the original does.
func formatSize(n uint64) string {
	f := float64(n)
	switch {
	case n < 1024:
		return strconv.FormatUint(n, 10) + " B"
	case f < 1024*1024:
		return trimFloat(f/1024) + " KiB"
	case f < 1024*1024*1024:
		return trimFloat(f/(1024*1024)) + " MiB"
	case f < 1024*1024*1024*1024:
		return trimFloat(f/(1024*1024*1024)) + " GiB"
	case f < 1024*1024*1024*1024*1024:
		return trimFloat(f/(1024*1024*1024*1024)) + " TiB"
	default:
		return trimFloat(f/(1024*1024*1024*1024*1024)) + " PiB"
	}
}

// trimFloat formats with one decimal, rounding half away from zero like Rust's {:.1}
func trimFloat(v float64) string {
	s := strconv.FormatFloat(v, 'f', 1, 64)
	return s
}

// signedSize formats the difference part of the report line
func signedSize(newSize, origSize uint64) string {
	if newSize > origSize {
		return "+" + formatSize(newSize-origSize)
	}
	return "-" + formatSize(origSize-newSize)
}

func signedPct(newSize, origSize uint64) string {
	if origSize == 0 {
		return "-0.00%"
	}
	pct := (float64(newSize) - float64(origSize)) / float64(origSize) * 100
	if newSize > origSize {
		return "+" + strconv.FormatFloat(pct, 'f', 2, 64) + "%"
	}
	return "-" + strconv.FormatFloat(math.Abs(pct), 'f', 2, 64) + "%"
}

// parseByteSize mimics the `bytesize` crate's FromStr implementation.
// It returns the parsed value or an error message.
func parseByteSize(s string) (uint64, string) {
	// plain integer
	if v, err := strconv.ParseUint(s, 10, 64); err == nil {
		return v, ""
	}
	// split number / unit: leading run of digits and '.'
	i := 0
	for i < len(s) && (isDigit(s[i]) || s[i] == '.') {
		i++
	}
	numStr := s[:i]
	unit := s[i:]
	numStr = strings.TrimSpace(numStr)
	var num float64
	var err error
	if numStr == "" {
		return 0, "couldn't parse \"" + s + "\" into a ByteSize, cannot parse float from empty string"
	}
	num, err = strconv.ParseFloat(numStr, 64)
	if err != nil {
		return 0, "couldn't parse \"" + s + "\" into a ByteSize, invalid float literal"
	}
	mult, ok := unitMultiplier(unit)
	if !ok {
		return 0, "couldn't parse \"" + unit + "\" into a known SI unit, Failed to parse unit \"" + unit + "\""
	}
	return uint64(num * float64(mult)), ""
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

// unitMultiplier maps a unit suffix to its byte multiplier.
// The leading whitespace is ignored, the rest must match exactly.
func unitMultiplier(unit string) (uint64, bool) {
	for len(unit) > 0 && (unit[0] == ' ' || unit[0] == '\t' || unit[0] == '\n' || unit[0] == '\r') {
		unit = unit[1:]
	}
	u := strings.ToLower(unit)
	m := map[string]uint64{
		"":    1,
		"b":   1,
		"k":   1000, "kb": 1000, "ki": 1024, "kib": 1024,
		"m":   1000 * 1000, "mb": 1000 * 1000, "mi": 1024 * 1024, "mib": 1024 * 1024,
		"g":   1000 * 1000 * 1000, "gb": 1000 * 1000 * 1000, "gi": 1024 * 1024 * 1024, "gib": 1024 * 1024 * 1024,
		"t":   1000 * 1000 * 1000 * 1000, "tb": 1000 * 1000 * 1000 * 1000, "ti": 1024 * 1024 * 1024 * 1024, "tib": 1024 * 1024 * 1024 * 1024,
		"p":   1000 * 1000 * 1000 * 1000 * 1000, "pb": 1000 * 1000 * 1000 * 1000 * 1000, "pi": 1024 * 1024 * 1024 * 1024 * 1024, "pib": 1024 * 1024 * 1024 * 1024 * 1024,
		"e":   1000 * 1000 * 1000 * 1000 * 1000 * 1000, "eb": 1000 * 1000 * 1000 * 1000 * 1000 * 1000, "ei": 1024 * 1024 * 1024 * 1024 * 1024 * 1024, "eib": 1024 * 1024 * 1024 * 1024 * 1024 * 1024,
	}
	v, ok := m[u]
	return v, ok
}

// minSavings is a parsed --min-savings threshold
type minSavings struct {
	isPercent bool
	percent   float64
	bytes     uint64
}

func (m minSavings) display(orig uint64) string {
	if m.isPercent {
		return strconv.FormatFloat(m.percent, 'f', 2, 64) + "%"
	}
	return formatSize(m.bytes)
}

// parseMinSavings parses the --min-savings value.
func parseMinSavings(s string) (minSavings, string) {
	v := strings.TrimSpace(s)
	if v == "" {
		return minSavings{}, "Value cannot be empty. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes"
	}
	badFmt := func() string {
		return "Invalid size format: '" + s + "'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes"
	}
	if strings.HasSuffix(v, "%") {
		p := strings.TrimSpace(v[:len(v)-1])
		f, err := strconv.ParseFloat(p, 64)
		if err != nil {
			return minSavings{}, "Invalid percentage value: '" + p + "'"
		}
		if f < 0 || f > 100 {
			return minSavings{}, "Percentage must be between 0 and 100, got " + formatRustFloat(f)
		}
		return minSavings{isPercent: true, percent: f}, ""
	}
	if n, err := strconv.ParseUint(v, 10, 64); err == nil {
		return minSavings{bytes: n}, ""
	}
	// size with unit: reuse the bytesize parser but report our own error
	if _, e := parseByteSize(v); e != "" {
		return minSavings{}, badFmt()
	}
	n, _ := parseByteSize(v)
	return minSavings{bytes: n}, ""
}

// formatRustFloat formats a float like Rust's Display for f64
func formatRustFloat(f float64) string {
	if f == math.Trunc(f) && math.Abs(f) < 1e15 {
		return strconv.FormatInt(int64(f), 10)
	}
	s := strconv.FormatFloat(f, 'g', -1, 64)
	// Rust prints plain decimals for normal ranges
	if i := strings.IndexByte(s, 'e'); i >= 0 {
		exp, _ := strconv.Atoi(s[i+1:])
		if exp >= -6 && exp <= 15 {
			s = strconv.FormatFloat(f, 'f', -1, 64)
		}
	}
	return s
}

func formatFloatDefault(f float64) string {
	return strconv.FormatFloat(f, 'f', -1, 64)
}
GOEOF
echo ok"}

