{"command": "cat > src/run.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
)

// task describes one file to be compressed
type task struct {
	src     string
	dst     string
	format  format
	w, h    uint32
	size    uint64
}

// result describes the outcome of one task
type result struct {
	task   *task
	status int // 0 success, 1 skipped, 2 error
	reason string
	newSize uint64
}

const (
	stSuccess = 0
	stSkipped = 1
	stError   = 2
)

// collectFiles walks the input paths and returns the files to process
func collectFiles(cfg *config, inputs []string) ([]task, bool) {
	var tasks []task
	seen := map[string]bool{}
	for _, in := range inputs {
		st, err := os.Stat(in)
		if err != nil {
			continue
		}
		if st.IsDir() {
			var found []string
			scanDir(in, cfg.recursive, &found)
			for _, f := range found {
				if !seen[f] {
					seen[f] = true
					tasks = append(tasks, task{src: f})
				}
			}
		} else if st.Mode().IsRegular() {
			if !seen[in] {
				seen[in] = true
				tasks = append(tasks, task{src: in})
			}
		}
	}
	// probe formats, drop unsupported files
	var out []task
	for i := range tasks {
		d, err := os.ReadFile(tasks[i].src)
		if err != nil {
			continue
		}
		f := sniffFormat(d)
		if f == fmtUnknown {
			continue
		}
		w, h, ok := imageSize(d, f)
		if !ok {
			continue
		}
		tasks[i].format = f
		tasks[i].w = w
		tasks[i].h = h
		tasks[i].size = uint64(len(d))
		out = append(out, tasks[i])
	}
	return out, true
}

func scanDir(dir string, recursive bool, out *[]string) {
	f, err := os.Open(dir)
	if err != nil {
		return
	}
	entries, err := f.ReadDir(-1)
	f.Close()
	if err != nil {
		return
	}
	var subdirs []string
	for _, e := range entries {
		p := filepath.Join(dir, e.Name())
		if e.IsDir() {
			subdirs = append(subdirs, p)
			continue
		}
		if e.Type().IsRegular() {
			*out = append(*out, p)
		}
	}
	if recursive {
		for _, s := range subdirs {
			scanDir(s, true, out)
		}
	}
}

// basePath computes the deepest common ancestor directory of the given files
func basePath(files []string) string {
	if len(files) == 0 {
		return ""
	}
	split := func(p string) []string {
		p = filepath.Clean(p)
		vol := filepath.VolumeName(p)
		rest := strings.TrimPrefix(p, vol)
		parts := strings.Split(rest, string(filepath.Separator))
		if vol != "" {
			return append([]string{vol}, parts...)
		}
		return parts
	}
	common := split(files[0])
	// drop the last component (the file itself)
	common = common[:len(common)-1]
	for _, f := range files[1:] {
		parts := split(f)
		parts = parts[:len(parts)-1]
		n := len(common)
		if len(parts) < n {
			n = len(parts)
		}
		i := 0
		for i < n && common[i] == parts[i] {
			i++
		}
		common = common[:i]
	}
	if len(common) == 0 {
		return string(filepath.Separator)
	}
	return filepath.Join(common...)
}

func outputPath(cfg *config, src, base string) string {
	name := filepath.Base(src)
