	i := (y*im.W + x) * 4
	im.Pix[i], im.Pix[i+1], im.Pix[i+2], im.Pix[i+3] = r, g, b, a
}

func (im *Image) Opaque() bool {
	for i := 3; i < len(im.Pix); i += 4 {
		if im.Pix[i] != 255 {
			return false
		}
	}
	return true
