func (im *Image) GrayLike() bool {
	for i := 0; i < len(im.Pix); i += 4 {
		if im.Pix[i] != im.Pix[i+1] || im.Pix[i+1] != im.Pix[i+2] {
			return false
		}
	}
	return true
}

