func (im *Image) Colors() int {
	if im.W <= 0 || im.H <= 0 {
		return 0
	}
	seen := make(map[uint32]bool, 1024)
	for i := 0; i < len(im.Pix); i += 4 {
		k := uint32(im.Pix[i])<<16 | uint32(im.Pix[i+1])<<8 | uint32(im.Pix[i+2])
		seen[k] = true
		if len(seen) > 1<<20 {
			return -1
		}
	}
	return len(seen)
}

