			for _, e := range ws {
				o := e.idx * 4
				w := e.w
				a += float32(row[o]) * w
				b += float32(row[o+1]) * w
				c += float32(row[o+2]) * w
				d += float32(row[o+3]) * w
			}
			o := (y*nw + x) * 4
			tmp[o], tmp[o+1], tmp[o+2], tmp[o+3] = a, b, c, d
		}
