	z4 += z2
	z5 := (tmp10 * 12873 + (1 << 14)) >> 15 // fix_1_501321110
	z5 += z3
	z6 := (tmp11 * -10896 + (1 << 14)) >> 15 // -fix_1_224646799
	z6 += z2
	z2 += (tmp13 * 7373 + (1 << 14)) >> 15 // fix_0_847711251... actually fix_0_8477
	tmp12 = z4 + z6
	out[1] = tmp12
	out[7] = z5 - z4
	tmp12 = z2 + z3
	out[3] = tmp12
	out[5] = z6 - z5
	out[1] = (out[1] + (1 << 13)) >> 14
	out[7] = (out[7] + (1 << 13)) >> 14
	out[3] = (out[3] + (1 << 13)) >> 14
	out[5] = (out[5] + (1 << 13)) >> 14
}

// forwardDCT computes the DCT of an 8x8 block of samples (already level shifted)
func forwardDCT(block *[64]int, qt *[64]int, out *[64]int) {
	fdct8x8(block)
	for i := 0; i < 64; i++ {
		v := block[i]
		q := qt[i]
		if v >= 0 {
			out[i] = (v + q/2) / q
		} else {
			out[i] = -((-v + q/2) / q)
		}
	}
}

// huffTable is a Huffman table with the code lengths and values
type huffTable struct {
	bits  [17]int
	vals  []uint8
	codes []uint32 // code for each value index
	sizes []uint8
	// lookup for encoding
	codeOf [256]uint32
	sizeOf [256]uint8
	nVals  int
}

// buildHuffman builds an optimized Huffman table from symbol counts
func buildHuffman(freq *[257]int) *huffTable {
	// libjpeg's jpeg_gen_optimal_table
	var bits [17]int
	var huffsize [257]uint8
	var huffcode [257]uint32
	var vals [257]uint8

	codesize := make([]int, 257)
	others := make([]int, 257) // -1 = none
	for i := 0; i < 257; i++ {
		others[i] = -1
	}
	for i := 0; i < 257; i++ {
		codesize[i] = 0
		if freq[i] != 0 {
			codesize[i] = 1
		}
	}
	for loop := true; loop; {
		// find the two smallest nonzero frequencies
		v1, v2 := -1, -1
		for i := 0; i <= 256; i++ {
			if freq[i] == 0 {
				continue
			}
			if v1 < 0 || freq[i] < freq[v1] {
				v2 = v1
				v1 = i
			} else if v2 < 0 || freq[i] < freq[v2] {
				v2 = i
			}
		}
		if v2 < 0 {
			break
		}
		f := freq[v1] + freq[v2]
		freq[v2] = 0
		freq[v1] = f
		// update code sizes
		for i := 0; i <= 256; i++ {
			if codesize[i] == 0 {
				continue
			}
		}
		var chain [2]int
		chain[0] = v1
		chain[1] = v2
		for c := 0; c < 2; c++ {
			i := chain[c]
			for i >= 0 {
				codesize[i]++
				if codesize[i] >= 32 {
					// too deep; break out (should not happen with our limit)
					i = -1
					break
				}
				i = others[i]
			}
		}
		// fix: walk the chains properly
		_ = chain
		for i := 0; i < 2; i++ {
			j := chain[i]
			for j >= 0 {
				codesize[j]++
				j = others[j]
			}
		}
		// undo the double increment from the first pass
		for i := 0; i <= 256; i++ {
			_ = i
		}
		others[v1] = v2
		freq[v1] = 0x7fffffff // mark as processed
		// stop when only one chain remains
		cnt := 0
		for i := 0; i <= 256; i++ {
			if codesize[i] > 0 {
				cnt++
			}
		}
		if cnt <= 1 {
			break
		}
	}
	// The above is convoluted; use a simpler heap based construction instead.
	return buildHuffmanSimple(freq)
}

// buildHuffmanSimple builds an optimal (length limited) Huffman table
func buildHuffmanSimple(freqIn *[257]int) *huffTable {
	freq := *freqIn
	type node struct {
		w     int
		left  int
		right int
		val   int
	}
	var nodes []node
	for i := 0; i < 256; i++ {
		if freq[i] > 0 {
			nodes = append(nodes, node{w: freq[i], val: i, left: -1, right: -1})
		}
	}
	if len(nodes) == 0 {
		// empty table: single code
		t := &huffTable{}
		t.bits[1] = 1
		t.vals = []uint8{0}
		t.finish()
		return t
	}
	// sort indices by weight ascending
	idx := make([]int, len(nodes))
	for i := range idx {
		idx[i] = i
	}
	sort.Slice(idx, func(a, b int) bool {
		if nodes[idx[a]].w != nodes[idx[b]].w {
			return nodes[idx[a]].w < nodes[idx[b]].w
		}
		return nodes[idx[a]].val < nodes[idx[b]].val
	})
	// build tree with a simple queue merge (package merge would be better but this
	// matches typical encoder output closely)
	weights := make([]int, len(nodes))
	for i, id := range idx {
		weights[i] = nodes[id].w
	}
	// repeatedly merge the two smallest
	type ent struct {
		w   int
		id  int // index into nodes, or -1 for internal
		l, r int
	}
	var q []ent
	for i, id := range idx {
		q = append(q, ent{w: weights[i], id: id, l: -1, r: -1})
	}
	for len(q) > 1 {
		// find the two smallest
		a, b := 0, 1
		if q[1].w < q[0].w {
			a, b = 1, 0
		}
		for i := 2; i < len(q); i++ {
			if q[i].w < q[a].w {
				b = a
				a = i
			} else if q[i].w < q[b].w {
				b = i
			}
		}
		na, nb := q[a], q[b]
		// remove a and b (remove the larger index first)
		hi := a
		if b > a {
			hi = b
		}
		lo := a + b - hi
		q = append(q[:hi], q[hi+1:]...)
		q = append(q[:lo], q[lo+1:]...)
		q = append(q, ent{w: na.w + nb.w, id: -1, l: na.id, r: nb.id})
		// store internal node
		nodes = append(nodes, node{w: na.w + nb.w, val: -1, left: na.id, right: nb.id})
		q[len(q)-1].id = len(nodes) - 1
	}
	root := q[0].id
	// compute code lengths
	depths := make([]int, len(nodes))
	var walk func(n, d int)
	walk = func(n, d int) {
		if n < 0 {
			return
		}
		if nodes[n].val >= 0 {
			if d == 0 {
				d = 1
			}
			depths[n] = d
			return
		}
		walk(nodes[n].left, d+1)
		walk(nodes[n].right, d+1)
	}
	walk(root, 0)
	// collect lengths
	var lens [17]int
	var syms []int
	for i, n := range nodes {
		if n.val >= 0 {
			d := depths[i]
			if d > 16 {
				d = 16
			}
			lens[d]++
			syms = append(syms, n.val)
		}
	}
	// If any length exceeded 16 we must rebalance: fall back to a canonical
	// length limited table.
	over := 0
	for d := 17; d < len(lens); d++ {
		over += lens[d]
		lens[d] = 0
	}
	t := &huffTable{}
	if over > 0 {
		// use a simple length limited assignment
		t.limitLengths(freqIn, syms)
		t.finish()
		return t
	}
	for d := 1; d <= 16; d++ {
		t.bits[d] = lens[d]
	}
	sort.Ints(syms)
	t.vals = make([]uint8, len(syms))
	for i, s := range syms {
		t.vals[i] = uint8(s)
	}
	t.finish()
	return t
}

// limitLengths assigns code lengths with the Kraft sum <= 1 constraint
func (t *huffTable) limitLengths(freq *[257]int, syms []int) {
	// simple approach: give all symbols length 8 (or fewer if not enough)
	n := len(syms)
	lens := make([]int, n)
	// compute the minimal lengths so that sum(2^-l) <= 1
	// use the "Huffman with length limit" via the package-merge-lite heuristic
	total := 0
	for _, s := range syms {
		total += freq[s]
	}
	if n == 1 {
		lens[0] = 1
	} else {
		// start with ceil(log2(n)) for all, then adjust
		l := 1
		for (1 << uint(l)) < n {
			l++
		}
		for i := range lens {
			lens[i] = l
		}
		// fix overflow: while sum(2^-l) > 1, increase the length of the least frequent
		for {
			sum := 0.0
			for _, ll := range lens {
				sum += 1.0 / float64(int(1)<<uint(ll))
			}
			if sum <= 1.0+1e-9 {
				break
			}
			// increase the length of the least frequent symbol
			mi := 0
			for i := 1; i < n; i++ {
				if lens[i] > lens[mi] {
					mi = i
				}
			}
			lens[mi]++
			if lens[mi] > 16 {
				break
			}
		}
	}
	var cnt [17]int
	for _, ll := range lens {
		if ll > 16 {
			ll = 16
		}
		cnt[ll]++
	}
	for d := 1; d <= 16; d++ {
		t.bits[d] = cnt[d]
	}
	sort.Ints(syms)
	t.vals = make([]uint8, len(syms))
	for i, s := range syms {
		t.vals[i] = uint8(s)
	}
}

// finish computes the canonical codes for the table
func (t *huffTable) finish() {
	t.nVals = len(t.vals)
	t.codes = make([]uint32, t.nVals)
	t.sizes = make([]uint8, t.nVals)
	code := uint32(0)
	k := 0
	for d := 1; d <= 16; d++ {
		for i := 0; i < t.bits[d]; i++ {
			t.codes[k] = code
			t.sizes[k] = uint8(d)
			if int(t.vals[k]) < 256 {
				t.codeOf[t.vals[k]] = code
				t.sizeOf[t.vals[k]] = uint8(d)
			}
			k++
			code++
		}
		code <<= 1
	}
}

// bitWriter accumulates bits and emits 0xFF stuffed bytes
type bitWriter struct {
	buf    bytes.Buffer
	acc    uint32
	nbits  int
	nBytes int
}

func (bw *bitWriter) put(code uint32, size int) {
	if size == 0 {
		return
	}
	bw.acc = (bw.acc << uint(size)) | (code & ((1 << uint(size)) - 1))
	bw.nbits += size
	for bw.nbits >= 8 {
		b := uint8((bw.acc >> uint(bw.nbits-8)) & 0xFF)
		bw.buf.WriteByte(b)
		bw.nBytes++
		if b == 0xFF {
			bw.buf.WriteByte(0)
			bw.nBytes++
		}
		bw.nbits -= 8
	}
}

func (bw *bitWriter) putBits(v uint32, n int) {
	if n <= 0 {
		return
	}
	if v>>uint(n-1) == 0 {
		// positive value: no adjustment
	} else {
		v = v & ((1 << uint(n)) - 1)
	}
	bw.put(v, n)
}

func (bw *bitWriter) flush() {
	if bw.nbits > 0 {
		fill := 8 - bw.nbits
		bw.put((1<<uint(fill))-1, fill)
		bw.nbits = 0
	}
}

// catBits returns the number of bits and the encoded value for a magnitude
func catBits(v int) (int, uint32) {
	if v < 0 {
		v = -v
	}
	nbits := 0
	t := v
	for t > 0 {
		nbits++
		t >>= 1
	}
	if nbits == 0 {
		return 0, 0
	}
	// encoded value: for positive v, v itself; for negative, v-1 in one's complement
	return nbits, uint32(v)
}
