package img

import (
	"bytes"
)

// compInfo describes a JPEG component
type compInfo struct {
	id        int
	h, v      int // sampling factors
	quantSel  int // quantization table index
	dcSel     int
	acSel     int
	blocksW   int // blocks per MCU row
	blocksH   int
	coeffs    []int16 // blocksW*blocksH*8*8 (in zigzag order)
}

// mcuGrid computes the MCU grid for the given sampling factors
func mcuGrid(w, h int, comps []compInfo) (mcusW, mcusH int) {
	maxH, maxV := 0, 0
	for _, c := range comps {
		if c.h > maxH {
			maxH = c.h
		}
		if c.v > maxV {
			maxV = c.v
		}
	}
	mcusW = (w + 8*maxH - 1) / (8 * maxH)
	mcusH = (h + 8*maxV - 1) / (8 * maxV)
	for i := range comps {
		comps[i].blocksW = mcusW * comps[i].h
		comps[i].blocksH = mcusH * comps[i].v
	}
	return
}

// rgbToYCbCr converts an RGBA image to Y, Cb, Cr planes
func rgbToYCbCr(im *Image) (y, cb, cr []uint8) {
	n := im.W * im.H
	y = make([]uint8, n)
	cb = make([]uint8, n)
	cr = make([]uint8, n)
	p := im.Pix
	for i := 0; i < n; i++ {
		r := int(p[i*4])
		g := int(p[i*4+1])
		b := int(p[i*4+2])
		yi := (19595*r + 38470*g + 7471*b + 32768) >> 16
		cbi := (-11056*r - 21712*g + 32768*b + 8421376) >> 16
		cri := (32768*r - 27440*g - 5328*b + 8421376) >> 16
		if yi < 0 {
			yi = 0
		} else if yi > 255 {
			yi = 255
		}
		if cbi < 0 {
			cbi = 0
		} else if cbi > 255 {
			cbi = 255
		}
		if cri < 0 {
			cri = 0
		} else if cri > 255 {
			cri = 255
		}
		y[i] = uint8(yi)
		cb[i] = uint8(cbi)
		cr[i] = uint8(cri)
	}
	return
}

// downsample averages the source plane into the component's grid
func downsample(src []uint8, sw, sh, dw, dh int) []uint8 {
	if dw == sw && dh == sh {
		return src
	}
	out := make([]uint8, dw*dh)
	sx := sw / dw
	sy := sh / dh
	for y := 0; y < dh; y++ {
		for x := 0; x < dw; x++ {
			sum := 0
			cnt := 0
			for dy := 0; dy < sy; dy++ {
				syy := y*sy + dy
				if syy >= sh {
					syy = sh - 1
				}
				for dx := 0; dx < sx; dx++ {
					sxx := x*sx + dx
					if sxx >= sw {
						sxx = sw - 1
					}
					sum += int(src[syy*sw+sxx])
					cnt++
				}
			}
			v := (sum + cnt/2) / cnt
			out[y*dw+x] = uint8(v)
		}
	}
	return out
}

// JpegEncOptions controls the JPEG encoder
type JpegEncOptions struct {
	Quality     int
	Subsampling string // 4:4:4, 4:2:2, 4:2:0, 4:1:1, auto
	Progressive bool
	Quant       [2][64]int
	Exif        []byte // APP1 payload (Exif\0\0 + tiff) to embed
}

// EncodeJPEG encodes the image to JPEG
func EncodeJPEG(im *Image, o JpegEncOptions) []byte {
	gray := im.GrayLike()
