			{id: 1, h: h, v: v, quantSel: 0, dcSel: 0, acSel: 0},
			{id: 2, h: 1, v: 1, quantSel: 1, dcSel: 1, acSel: 1},
			{id: 3, h: 1, v: 1, quantSel: 1, dcSel: 1, acSel: 1},
