func writeJPEG(im *Image, comps []compInfo, o JpegEncOptions, gray bool) []byte {
	var buf bytes.Buffer
	// SOI
	buf.Write([]byte{0xFF, 0xD8})
	// APP0 JFIF
	app0 := []byte{'J', 'F', 'I', 'F', 0, 1, 1, 0, 0, 1, 0, 1, 0, 0}
	segMarker(&buf, 0xE0, app0)
	// EXIF
	if len(o.Exif) > 0 {
		segMarker(&buf, 0xE1, o.Exif)
	}
	// DQT
	pq := 0
	for t := 0; t < 2; t++ {
		for i := 0; i < 64; i++ {
			if o.Quant[t][i] > 255 {
				pq = 1
			}
		}
	}
	if pq == 1 {
		for t := 0; t < (2 - boolToInt(gray)); t++ {
			var seg []byte
			seg = append(seg, byte(0x10|t))
			for i := 0; i < 64; i++ {
				v := o.Quant[t][i]
				seg = append(seg, byte(v>>8), byte(v))
			}
			segMarker(&buf, 0xDB, seg)
		}
	} else {
		for t := 0; t < (2 - boolToInt(gray)); t++ {
			seg := []byte{byte(t)}
			for i := 0; i < 64; i++ {
				seg = append(seg, byte(o.Quant[t][i]))
			}
			segMarker(&buf, 0xDB, seg)
		}
	}
	// SOF
	prec := 0
	s := []byte{byte(prec)}
	s = append(s, byte(im.H>>8), byte(im.H), byte(im.W>>8), byte(im.W), byte(len(comps)))
	for _, c := range comps {
		s = append(s, byte(c.id), byte(c.h<<4|c.v), byte(c.quantSel))
	}
	sOf := 0xC0
	if o.Progressive {
		sOf = 0xC2
	}
	segMarker(&buf, sOf, s)

	// build scans
	scans := buildScans(comps, o.Progressive)
	// encode each scan
	var dhts []dhtEntry
	for si, sc := range scans {
		// compute the huffman tables needed for this scan
		tables := scanTables(comps, sc, o.Quant, gray)
		for i := range tables {
			dhts = append(dhts, tables[i])
		}
		// SOS + entropy data
		sos := []byte{byte(len(sc.comps))}
		for _, ci := range sc.comps {
			sos = append(sos, byte(comps[ci].id), byte(comps[ci].dcSel<<4|comps[ci].acSel))
		}
		sos = append(sos, byte(sc.ss), byte(sc.se), byte(sc.ah<<4|sc.al))
		segMarker(&buf, 0xDA, sos)
		encodeScan(&buf, comps, sc, tables, o.Quant)
		if si == len(scans)-1 {
		}
	}
	// DHT segments: emit all tables used, grouped per scan as the original does
	buf.Write([]byte{0xFF, 0xD9})
	return buf.Bytes()
}
