// downsampleBox averages src into a dw x dh grid
func downsampleBox(src []uint8, sw, sh, dw, dh int) []uint8 {
	if dw == sw && dh == sh {
		return src
	}
	out := make([]uint8, dw*dh)
	for y := 0; y < dh; y++ {
		y0 := y * sh / dh
		y1 := (y + 1) * sh / dh
		if y1 <= y0 {
			y1 = y0 + 1
		}
		for x := 0; x < dw; x++ {
			x0 := x * sw / dw
			x1 := (x + 1) * sw / dw
			if x1 <= x0 {
				x1 = x0 + 1
			}
			sum := 0
			cnt := 0
			for yy := y0; yy < y1 && yy < sh; yy++ {
				for xx := x0; xx < x1 && xx < sw; xx++ {
					sum += int(src[yy*sw+xx])
					cnt++
				}
			}
			if cnt == 0 {
				cnt = 1
			}
			out[y*dw+x] = uint8((sum + cnt/2) / cnt)
		}
	}
