// scan describes one entropy coded scan
type scan struct {
	comps []int // component indices
	ss    int
	se    int
	ah    int
	al    int
	// table selection per component (dc, ac)
	dctab []int
	actab []int
}

// buildScans returns the scan layout
func buildScans(comps []compInfo, progressive bool) []scan {
	var out []scan
	if !progressive {
		all := make([]int, len(comps))
		for i := range comps {
			all[i] = i
		}
		out = append(out, scan{comps: all, ss: 0, se: 63})
		return out
	}
	all := make([]int, len(comps))
	for i := range comps {
		all[i] = i
	}
	out = append(out, scan{comps: all, ss: 0, se: 0})
	for i := range comps {
		out = append(out, scan{comps: []int{i}, ss: 1, se: 5})
		out = append(out, scan{comps: []int{i}, ss: 6, se: 63})
	}
	return out
}

type dhtEntry struct {
	tclass int // 0 = DC, 1 = AC
	id     int
	t      *huffTable
}

// scanTables builds the huffman tables used by a scan (optimizing per scan)
func scanTables(comps []compInfo, sc scan, quant [2][64]int, gray bool) []dhtEntry {
	var out []dhtEntry
	// assign table ids
	dcIds := map[int]int{}
	acIds := map[int]int{}
	nextDC, nextAC := 0, 0
	for _, ci := range sc.comps {
		key := comps[ci].quantSel
		if _, ok := dcIds[key]; !ok {
			dcIds[key] = nextDC
			nextDC++
		}
		if _, ok := acIds[key]; !ok {
			acIds[key] = nextAC
			nextAC++
		}
		comps[ci].dcSel = dcIds[key]
		comps[ci].acSel = acIds[key]
	}
	// gather statistics
	dcStats := make([][257]int, nextDC)
	acStats := make([][257]int, nextAC)
	gatherStats(comps, sc, dcStats, acStats)
	for id := 0; id < nextDC; id++ {
		out = append(out, dhtEntry{tclass: 0, id: id, t: buildHuffmanSimple(&dcStats[id])})
	}
	for id := 0; id < nextAC; id++ {
		out = append(out, dhtEntry{tclass: 1, id: id, t: buildHuffmanSimple(&acStats[id])})
	}
	return out
}

// gatherStats counts the symbols that a scan will emit
func gatherStats(comps []compInfo, sc scan, dcStats [][257]int, acStats [][257]int) {
	if sc.se == 0 {
		// DC only scan (interleaved)
		for _, ci := range sc.comps {
			c := &comps[ci]
			st := &dcStats[c.dcSel]
			prev := 0
			n := len(c.coeffs) / 64
			for b := 0; b < n; b++ {
				dc := int(c.coeffs[b*64])
				diff := dc - prev
				prev = dc
				cat := category(diff)
				if cat > 15 {
					cat = 15
				}
				st[cat]++
				for i := 1; i < cat; i++ {
					st[256]++ // 0xFF stuff bytes are not huffman symbols
				}
			}
		}
		return
	}
	if len(sc.comps) == 1 {
		c := &comps[sc.comps[0]]
		st := &acStats[c.acSel]
		n := len(c.coeffs) / 64
		for b := 0; b < n; b++ {
			run := 0
			for k := sc.ss; k <= sc.se; k++ {
				v := int(c.coeffs[b*64+k])
				if v == 0 {
					run++
					if run == 16 {
						st[0xF0]++
						run = 0
					}
					continue
				}
				cat := category(v)
				if cat > 10 {
					cat = 10
				}
				for run > 15 {
					st[0xF0]++
					run -= 16
				}
				st[run*16+cat]++
				run = 0
			}
			if run > 0 {
				st[0x00]++ // EOB
			}
		}
		return
	}
	// interleaved AC (baseline)
	for _, ci := range sc.comps {
		c := &comps[ci]
		st := &acStats[c.acSel]
		n := len(c.coeffs) / 64
		for b := 0; b < n; b++ {
			run := 0
			end := sc.se
			if end > 63 {
				end = 63
			}
			for k := sc.ss; k <= end; k++ {
				v := int(c.coeffs[b*64+k])
				if v == 0 {
					run++
					if run == 16 {
						st[0xF0]++
						run = 0
					}
					continue
				}
				cat := category(v)
				if cat > 10 {
					cat = 10
				}
				for run > 15 {
					st[0xF0]++
					run -= 16
				}
				st[run*16+cat]++
				run = 0
			}
			if run > 0 {
				st[0x00]++
			}
		}
	}
}

// encodeScan writes the entropy coded data of a scan
func encodeScan(buf *bytes.Buffer, comps []compInfo, sc scan, tables []dhtEntry, quant [2][64]int) {
	dcTabs := map[int]*huffTable{}
	acTabs := map[int]*huffTable{}
	for _, e := range tables {
		if e.tclass == 0 {
			dcTabs[e.id] = e.t
		} else {
			acTabs[e.id] = e.t
		}
	}
	bw := &bitWriter{}
	if sc.se == 0 {
		// interleaved DC
		prevs := make([]int, len(comps))
		n := len(comps[sc.comps[0]].coeffs) / 64
		for b := 0; b < n; b++ {
			for _, ci := range sc.comps {
				c := &comps[ci]
				dc := int(c.coeffs[b*64])
				diff := dc - prevs[ci]
				prevs[ci] = dc
				t := dcTabs[c.dcSel]
				cat := category(diff)
				if cat > 15 {
					cat = 15
				}
				bw.put(t.codeOf[cat], int(t.sizeOf[cat]))
				if cat > 0 {
					bw.putMagnitude(diff, cat)
				}
			}
		}
	} else if len(sc.comps) == 1 {
		c := &comps[sc.comps[0]]
		t := acTabs[c.acSel]
		n := len(c.coeffs) / 64
		for b := 0; b < n; b++ {
			run := 0
			for k := sc.ss; k <= sc.se; k++ {
				v := int(c.coeffs[b*64+k])
				if v == 0 {
					run++
					continue
				}
				cat := category(v)
				if cat > 10 {
					cat = 10
				}
				for run > 15 {
					bw.put(t.codeOf[0xF0], int(t.sizeOf[0xF0]))
					run -= 16
				}
				sym := run*16 + cat
				bw.put(t.codeOf[sym], int(t.sizeOf[sym]))
				bw.putMagnitude(v, cat)
				run = 0
			}
			if run > 0 {
				bw.put(t.codeOf[0x00], int(t.sizeOf[0x00]))
			}
		}
	} else {
		n := len(comps[sc.comps[0]].coeffs) / 64
		for b := 0; b < n; b++ {
			for _, ci := range sc.comps {
				c := &comps[ci]
				t := acTabs[c.acSel]
				run := 0
				end := sc.se
				if end > 63 {
					end = 63
				}
				for k := sc.ss; k <= end; k++ {
					v := int(c.coeffs[b*64+k])
					if v == 0 {
						run++
						continue
					}
					cat := category(v)
					if cat > 10 {
						cat = 10
					}
					for run > 15 {
						bw.put(t.codeOf[0xF0], int(t.sizeOf[0xF0]))
						run -= 16
					}
					sym := run*16 + cat
					bw.put(t.codeOf[sym], int(t.sizeOf[sym]))
					bw.putMagnitude(v, cat)
					run = 0
				}
				if run > 0 {
					bw.put(t.codeOf[0x00], int(t.sizeOf[0x00]))
				}
			}
		}
	}
	bw.flush()
	buf.Write(bw.buf.Bytes())
}

func segMarker(buf *bytes.Buffer, marker int, payload []byte) {
	buf.WriteByte(0xFF)
	buf.WriteByte(byte(marker))
	buf.WriteByte(byte(len(payload) >> 8))
	buf.WriteByte(byte(len(payload)))
	buf.Write(payload)
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

// sortInts is a tiny helper (kept for clarity)
func sortInts(a []int) { sort.Ints(a) }
