// mcuGrid computes the MCU grid and per component block counts
func mcuGrid(w, h int, comps []compInfo) (int, int) {
	maxH, maxV := 0, 0
	for _, c := range comps {
		if c.h > maxH {
			maxH = c.h
		}
		if c.v > maxV {
			maxV = c.v
		}
	}
	mcusW := (w + 8*maxH - 1) / (8 * maxH)
	mcusH := (h + 8*maxV - 1) / (8 * maxV)
	for i := range comps {
		comps[i].blocksW = mcusW * comps[i].h
		comps[i].blocksH = mcusH * comps[i].v
	}
	return mcusW, mcusH
}

// rgbToYCbCr converts RGBA to Y, Cb, Cr planes (libjpeg fixed point constants)
func rgbToYCbCr(im *Image) ([]uint8, []uint8, []uint8) {
	n := im.W * im.H
	y := make([]uint8, n)
	cb := make([]uint8, n)
	cr := make([]uint8, n)
	p := im.Pix
	for i := 0; i < n; i++ {
		r := int(p[i*4])
		g := int(p[i*4+1])
		b := int(p[i*4+2])
		yi := (19595*r + 38470*g + 7471*b + 32768) >> 16
		cbi := (-11056*r - 21712*g + 32768*b + 8421376) >> 16
		cri := (32768*r - 27440*g - 5328*b + 8421376) >> 16
		if yi < 0 {
			yi = 0
		} else if yi > 255 {
			yi = 255
		}
		if cbi < 0 {
			cbi = 0
		} else if cbi > 255 {
			cbi = 255
		}
		if cri < 0 {
			cri = 0
		} else if cri > 255 {
			cri = 255
		}
		y[i] = uint8(yi)
		cb[i] = uint8(cbi)
		cr[i] = uint8(cri)
	}
	return y, cb, cr
}

// downsampleBox averages src into a dw x dh grid
func downsampleBox(src []uint8, sw, sh, dw, dh int) []uint8 {
	if dw == sw && dh == sh {
		return src
	}
	out := make([]uint8, dw*dh)
	for y := 0; y < dh; y++ {
		y0 := y * sh / dh
		y1 := (y + 1) * sh / dh
		if y1 <= y0 {
			y1 = y0 + 1
		}
		for x := 0; x < dw; x++ {
			x0 := x * sw / dw
			x1 := (x + 1) * sw / dw
			if x1 <= x0 {
				x1 = x0 + 1
			}
			sum := 0
			cnt := 0
			for yy := y0; yy < y1 && yy < sh; yy++ {
				for xx := x0; xx < x1 && xx < sw; xx++ {
					sum += int(src[yy*sw+xx])
					cnt++
				}
			}
			if cnt == 0 {
				cnt = 1
			}
			out[y*dw+x] = uint8((sum + cnt/2) / cnt)
		}
	}
	return out
}

