package img

import (
	"bytes"
)

// writeJPEG assembles the JPEG file
func writeJPEG(im *Image, comps []compInfo, o JpegEncOptions, gray bool) []byte {
	var buf bytes.Buffer
	buf.Write([]byte{0xFF, 0xD8})
	app0 := []byte{'J', 'F', 'I', 'F', 0, 1, 1, 0, 0, 1, 0, 1, 0, 0}
	segMarker(&buf, 0xE0, app0)
	if len(o.Exif) > 0 {
		segMarker(&buf, 0xE1, o.Exif)
	}
	// DQT (single segment with all tables)
	pq := 0
	for t := 0; t < 2; t++ {
		for i := 0; i < 64; i++ {
			if o.Quant[t][i] > 255 {
				pq = 1
			}
		}
	}
	ntab := 2
	if gray {
		ntab = 1
	}
	var dqt []byte
	if pq == 1 {
		for t := 0; t < ntab; t++ {
			dqt = append(dqt, byte(0x10|t))
			for i := 0; i < 64; i++ {
				v := o.Quant[t][i]
				dqt = append(dqt, byte(v>>8), byte(v&0xFF))
			}
		}
	} else {
		for t := 0; t < ntab; t++ {
			dqt = append(dqt, byte(t))
			for i := 0; i < 64; i++ {
				dqt = append(dqt, byte(o.Quant[t][i]))
			}
		}
	}
	segMarker(&buf, 0xDB, dqt)
	// SOF
	sOf := 0xC0
	if o.Progressive {
		sOf = 0xC2
	}
	s := []byte{0}
	s = append(s, byte(im.H>>8), byte(im.H&0xFF), byte(im.W>>8), byte(im.W&0xFF), byte(len(comps)))
	for _, c := range comps {
		s = append(s, byte(c.id), byte(c.h<<4|c.v), byte(c.quantSel))
	}
	segMarker(&buf, sOf, s)

	scans := buildScans(comps, o.Progressive)
	for _, sc := range scans {
		tables := scanTables(comps, sc, o.Quant, gray)
		for _, e := range tables {
			var seg []byte
			seg = append(seg, byte(e.tclass<<4|e.id))
			seg = append(seg, e.t.bits[1:17]...)
			seg = append(seg, e.t.vals...)
			segMarker(&buf, 0xC4, seg)
		}
		sos := []byte{byte(len(sc.comps))}
		for _, ci := range sc.comps {
			sos = append(sos, byte(comps[ci].id), byte(comps[ci].dcSel<<4|comps[ci].acSel))
		}
		sos = append(sos, byte(sc.ss), byte(sc.se), byte(sc.ah<<4|sc.al))
		segMarker(&buf, 0xDA, sos)
		encodeScan(&buf, comps, sc, tables, o.Quant)
	}
	buf.Write([]byte{0xFF, 0xD9})
	return buf.Bytes()
}
