extern size_t WebPEncodeLosslessRGBA(const u8* rgba, int width, int height, int stride, u8** out);
extern u8* WebPDecodeRGBA(const u8* data, size_t data_size, int* width, int* height);
extern int WebPGetInfo(const u8* data, size_t data_size, int* width, int* height);
extern void WebPFree(void* ptr);

static size_t enc_lossy(const u8* rgba, int w, int h, int stride, float q, u8** out) {
    return WebPEncodeRGBA(rgba, w, h, stride, q, out);
}
static size_t enc_lossless(const u8* rgba, int w, int h, int stride, u8** out) {
    return WebPEncodeLosslessRGBA(rgba, w, h, stride, out);
}
static u8* dec(const u8* data, size_t n, int* w, int* h) { return WebPDecodeRGBA(data, n, w, h); }
static int info(const u8* data, size_t n, int* w, int* h) { return WebPGetInfo(data, n, w, h); }

#cgo LDFLAGS: -L/usr/lib/x86_64-linux-gnu -l:libwebp.so.7
*/
import "C"

import (
	"errors"
	"unsafe"
)

// DecodeWebP decodes a webp image (first frame)
func DecodeWebP(data []byte) (*Image, error) {
	var w, h C.int
	var src *C.u8
	if len(data) > 0 {
		src = (*C.u8)(unsafe.Pointer(&data[0]))
	}
	p := C.dec(src, C.size_t(len(data)), &w, &h)
	if p == nil {
		return nil, errors.New("null_decoder")
	}
	defer C.WebPFree(unsafe.Pointer(p))
	n := int(w) * int(h) * 4
	out := New(int(w), int(h))
	copy(out.Pix, (*[1 << 30]byte)(unsafe.Pointer(p))[:n:n])
	return out, nil
}

// EncodeWebP encodes an image as webp
func EncodeWebP(im *Image, quality float64, lossless bool) ([]byte, error) {
	if im.W <= 0 || im.H <= 0 {
		return nil, errors.New("null_decoder")
	}
	var out *C.u8
	var size C.size_t
	src := (*C.u8)(unsafe.Pointer(&im.Pix[0]))
	stride := im.W * 4
	if lossless {
		size = C.enc_lossless(src, C.int(im.W), C.int(im.H), C.int(stride), &out)
	} else {
		size = C.enc_lossy(src, C.int(im.W), C.int(im.H), C.int(stride), C.float(quality), &out)
	}
	if size == 0 || out == nil {
		return nil, errors.New("null_encoder")
	}
	defer C.WebPFree(unsafe.Pointer(out))
	res := make([]byte, size)
	copy(res, (*[1 << 30]byte)(unsafe.Pointer(out))[:size:size])
	return res, nil
}
