// chunk is a raw PNG chunk
type chunk struct {
	typ string
	data []byte
}

// ancillary PNG chunks that are preserved on re-encode
var keepChunks = map[string]bool{
	"gAMA": true, "cHRM": true, "sRGB": true, "iCCP": true, "tEXt": true,
	"zTXt": true, "iTXt": true, "pHYs": true, "sBIT": true, "bKGD": true,
	"tIME": true, "hIST": true, "sPLT": true, "oFFs": true, "pCAL": true,
	"gIFg": true, "gIFx": true, "eXIf": true, "acHP": true, "cICP": true,
	"mDCV": true, "cLLI": true,
}

// DecodePNG decodes a PNG file
func DecodePNG(data []byte) (*Image, []chunk, error) {
	d, err := pngdec.Decode(bytes.NewReader(data))
	if err != nil {
		return nil, nil, translatePNGErr(err)
	}
	var chunks []chunk
	pos := 8
	for pos+8 <= len(data) {
		ln := binary.BigEndian.Uint32(data[pos : pos+4])
		typ := string(data[pos+4 : pos+8])
		if pos+12+int(ln) > len(data) {
			break
		}
		payload := data[pos+8 : pos+8+int(ln)]
		switch typ {
		case "IHDR", "PLTE", "IDAT", "IEND", "tRNS", "fdAT", "fcTL", "acTL":
			// regenerated
		default:
			if keepChunks[typ] {
				chunks = append(chunks, chunk{typ: typ, data: append([]byte(nil), payload...)})
			}
		}
		pos += 12 + int(ln)
