	return im, chunks, nil
}

func fromGoImage(d image.Image) (*Image, error) {
	b := d.Bounds()
	w, h := b.Dx(), b.Dy()
	out := New(w, h)
	switch src := d.(type) {
	case *image.Paletted:
		pal := src.Palette
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				c := pal[src.ColorIndexAt(x, y)]
				r, g, bb, a := c.RGBA()
				out.Set(x, y, uint8(r>>8), uint8(g>>8), uint8(bb>>8), uint8(a>>8))
			}
		}
	case *image.RGBA:
		for y := 0; y < h; y++ {
			copy(out.Pix[y*w*4:(y+1)*w*4], src.Pix[y*src.Stride:y*src.Stride+w*4])
		}
	case *image.NRGBA:
		for y := 0; y < h; y++ {
			copy(out.Pix[y*w*4:(y+1)*w*4], src.Pix[y*src.Stride:y*src.Stride+w*4])
		}
	case *image.Gray:
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				v := src.GrayAt(x, y).Y
				out.Set(x, y, v, v, v, 255)
			}
		}
	case *image.Gray16:
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				v := uint8(src.Gray16At(x, y).Y >> 8)
				out.Set(x, y, v, v, v, 255)
			}
