	case *image.NRGBA64:
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				c := src.NRGBA64At(x, y)
				out.Set(x, y, uint8(c.R>>8), uint8(c.G>>8), uint8(c.B>>8), uint8(c.A>>8))
			}
		}
	case *image.CMYK:
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				c := src.CMYKAt(x, y)
				r, g, bb := cmykToRGB(c.C, c.M, c.Y, c.K)
				out.Set(x, y, r, g, bb, 255)
			}
		}
	default:
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				r, g, bb, a := d.At(x, y).RGBA()
				out.Set(x, y, uint8(r>>8), uint8(g>>8), uint8(bb>>8), uint8(a>>8))
			}
		}
	}
	return out, nil
}

func cmykToRGB(c, m, y, k uint8) (uint8, uint8, uint8) {
	r := uint8(255 - int(c)*(255-int(k))/255)
	g := uint8(255 - int(m)*(255-int(k))/255)
	b := uint8(255 - int(y)*(255-int(k))/255)
	return r, g, b
}

// translatePNGErr maps decoder errors to the messages of the original tool
func translatePNGErr(err error) error {
	msg := err.Error()
	switch {
	case msg == "png: invalid format: not a PNG file":
		return errors.New("Invalid data found; unable to read PNG file")
	case len(msg) > 0:
		return errors.New("Invalid data found; unable to read PNG file")
	}
	return err
}

// pngColorType chooses the PNG color type for encoding
const (
	ctGray = 0
	ctRGB = 2
	ctPalette = 3
	ctGrayAlpha = 4
	ctRGBA = 6
)

type pngPlan struct {
	colorType int
	bitDepth  int
	palette   []uint8 // RGB triples
	trns      []uint8
	// pixel data (bytes per pixel as stored)
	raw     []byte
	width   int
	height  int
	bpp     int // bytes per pixel for filtering
}

// planPNG decides how to store the image
func planPNG(im *Image, lossy bool, q int) *pngPlan {
	w, h := im.W, im.H
	if lossy {
		return planPalette(im, q)
	}
	opaque := im.Opaque()
	gray := im.GrayLike()
	if gray && opaque {
		raw := make([]byte, w*h)
		for i := 0; i < w*h; i++ {
			raw[i] = im.Pix[i*4]
		}
		return &pngPlan{colorType: ctGray, bitDepth: 8, raw: raw, width: w, height: h, bpp: 1}
	}
	if gray {
		raw := make([]byte, w*h*2)
		for i := 0; i < w*h; i++ {
			raw[i*2] = im.Pix[i*4]
			raw[i*2+1] = im.Pix[i*4+3]
		}
		return &pngPlan{colorType: ctGrayAlpha, bitDepth: 8, raw: raw, width: w, height: h, bpp: 2}
	}
	if opaque {
		raw := make([]byte, w*h*3)
		for i := 0; i < w*h; i++ {
			raw[i*3] = im.Pix[i*4]
			raw[i*3+1] = im.Pix[i*4+1]
			raw[i*3+2] = im.Pix[i*4+2]
		}
		return &pngPlan{colorType: ctRGB, bitDepth: 8, raw: raw, width: w, height: h, bpp: 3}
	}
	return &pngPlan{colorType: ctRGBA, bitDepth: 8, raw: append([]byte(nil), im.Pix...), width: w, height: h, bpp: 4}
}

// planPalette builds an indexed representation (used for lossy encoding and
// for lossless images with few colors)
func planPalette(im *Image, q int) *pngPlan {
	w, h := im.W, im.H
	n := w * h
	colors := make(map[uint32]int, 300)
	for i := 0; i < n; i++ {
		k := uint32(im.Pix[i*4])<<16 | uint32(im.Pix[i*4+1])<<8 | uint32(im.Pix[i*4+2])
		colors[k]++
	}
	// build palette (most frequent first)
	type entry struct {
		k uint32
		c int
	}
	list := make([]entry, 0, len(colors))
	for k, c := range colors {
		list = append(list, entry{k, c})
	}
	// sort by count desc then by value
	for i := 0; i < len(list); i++ {
		for j := i + 1; j < len(list); j++ {
			if list[j].c > list[i].c || (list[j].c == list[i].c && list[j].k < list[i].k) {
				list[i], list[j] = list[j], list[i]
			}
		}
	}
	max := len(list)
	if max > 256 {
		max = 256
	}
	pal := list[:max]
	idx := make(map[uint32]int, len(pal))
	for i, e := range pal {
		idx[e.k] = i
	}
	var trns []byte
	hasAlpha := false
	for i := 0; i < n; i++ {
		if im.Pix[i*4+3] != 255 {
			hasAlpha = true
		}
	}
	indices := make([]byte, n)
	if hasAlpha {
		// add fully transparent entry if needed
		// palette entries store rgb; transparency handled via tRNS with alpha per entry
		// combine alpha into the palette: allow up to 256 entries of (rgb,alpha)
		comb := make(map[uint64]int, 300)
		var palRGB []uint8
		var palA []uint8
		for _, e := range pal {
			comb[uint64(e.k)<<8|255] = len(palRGB)/3
			palRGB = append(palRGB, uint8(e.k>>16), uint8(e.k>>8), uint8(e.k))
			palA = append(palA, 255)
		}
		for i := 0; i < n; i++ {
			k := uint32(im.Pix[i*4])<<16 | uint32(im.Pix[i*4+1])<<8 | uint32(im.Pix[i*4+2])
			a := im.Pix[i*4+3]
			key := uint64(k)<<8 | uint64(a)
			if p, ok := comb[key]; ok {
				indices[i] = byte(p)
				continue
			}
			if len(palRGB)/3 < 256 {
				comb[key] = len(palRGB) / 3
				palRGB = append(palRGB, uint8(k>>16), uint8(k>>8), uint8(k))
				palA = append(palA, a)
				indices[i] = byte(comb[key])
			} else {
				indices[i] = 0
			}
		}
		bd := 8
		if len(palRGB)/3 <= 16 {
			bd = 4
		}
		return &pngPlan{colorType: ctPalette, bitDepth: bd, palette: palRGB, trns: palA,
			raw: packIndices(indices, bd), width: w, height: h, bpp: 1}
	}
	for i := 0; i < n; i++ {
		k := uint32(im.Pix[i*4])<<16 | uint32(im.Pix[i*4+1])<<8 | uint32(im.Pix[i*4+2])
		indices[i] = byte(idx[k])
	}
	bd := 8
	if len(pal) <= 16 {
		bd = 4
	}
	var pl []uint8
	for _, e := range pal {
		pl = append(pl, uint8(e.k>>16), uint8(e.k>>8), uint8(e.k))
	}
	return &pngPlan{colorType: ctPalette, bitDepth: bd, palette: pl, raw: packIndices(indices, bd), width: w, height: h, bpp: 1}
}

func packIndices(idx []byte, bitDepth int) []byte {
	if bitDepth == 8 {
		return idx
	}
	// 4 bit packing
	out := make([]byte, (len(idx)+1)/2)
	for i := 0; i < len(idx); i += 2 {
		hi := idx[i] & 0xF
		lo := uint8(0)
		if i+1 < len(idx) {
			lo = idx[i+1] & 0xF
		}
		out[i/2] = hi<<4 | lo
	}
	return out
}

// filterRow applies a PNG filter to a row
func filterRow(ft int, bpp int, cur, prev []byte) []byte {
	n := len(cur)
	out := make([]byte, n)
	switch ft {
	case 0:
		copy(out, cur)
	case 1:
		for i := 0; i < n; i++ {
			a := 0
			if i >= bpp {
				a = int(cur[i-bpp])
			}
			out[i] = cur[i] - byte(a)
		}
	case 2:
		for i := 0; i < n; i++ {
			out[i] = cur[i] - prev[i]
		}
	case 3:
		for i := 0; i < n; i++ {
			a := 0
			if i >= bpp {
				a = int(cur[i-bpp])
			}
			out[i] = cur[i] - byte((a+int(prev[i]))/2)
		}
	case 4:
		for i := 0; i < n; i++ {
			a := 0
			if i >= bpp {
				a = int(cur[i-bpp])
			}
			b := int(prev[i])
			c := 0
			if i >= bpp {
				c = int(prev[i-bpp])
			}
			p := a + b - c
			pa := abs(p - a)
			pb := abs(p - b)
			pc := abs(p - c)
			pr := a
			if pa > pb {
				pr = b
			}
			if pb > pc {
				pr = c
			}
			out[i] = cur[i] - byte(pr)
		}
	}
	return out
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func sumAbs(b []byte) int {
	s := 0
	for _, v := range b {
		if v > 127 {
			s += 256 - int(v)
		} else {
			s += int(v)
		}
	}
	return s
}

// EncodePNG encodes the image as a PNG file
func EncodePNG(im *Image, optLevel int, zopfli bool, chunks []chunk) []byte {
	plan := planPNG(im, false, 0)
	return encodePNGPlan(plan, optLevel, zopfli, chunks)
}

func encodePNGPlan(plan *pngPlan, optLevel int, zopfli bool, chunks []chunk) []byte {
	w, h := plan.width, plan.height
	bd := plan.bitDepth
	// build the raw scanlines (filter byte 0)
	bpp := plan.bpp
	rowBytes := (w*bpp*bd + 7) / 8
	raw := make([]byte, 0, h*(rowBytes+1))
	for y := 0; y < h; y++ {
		raw = append(raw, 0)
		raw = append(raw, plan.raw[y*rowBytes:(y+1)*rowBytes]...)
	}
	// candidate filters
	var filters []int
	fixed := []int{0, 1, 2, 3, 4}
	switch optLevel {
	case 0:
		filters = []int{0}
	case 1, 2:
		filters = []int{-1} // adaptive
	case 3:
		filters = []int{-1}
	case 4, 5, 6:
		filters = append([]int{-1}, fixed...)
	}
	type combo struct {
		filter   int
		level    int
		strategy int
	}
	var levels []int
	var strategies []int
	switch optLevel {
	case 0:
		levels = []int{6}
		strategies = []int{0}
	case 1, 2:
		levels = []int{9}
		strategies = []int{0}
	case 3:
		levels = []int{6, 9}
		strategies = []int{0}
	case 4:
		levels = []int{9}
		strategies = []int{0}
	case 5:
		levels = []int{6, 9}
		strategies = []int{0}
	default:
		levels = []int{6, 9}
		strategies = []int{0, 1, 2, 3, 4}
	}
	if zopfli {
		strategies = []int{0, 1, 2, 3, 4}
	}
	best := -1
	var bestData []byte
	for _, ft := range filters {
		var filtered []byte
		if ft == -1 {
			filtered = adaptiveFilter(raw, rowBytes, bpp, h)
		} else {
			filtered = fixedFilter(raw, ft, rowBytes, bpp, h)
		}
		for _, lv := range levels {
			for _, st := range strategies {
				data, ok := deflateRaw(filtered, lv, st)
				if !ok {
					continue
				}
				if best < 0 || len(data) < best {
					best = len(data)
					bestData = data
				}
			}
		}
	}
	// assemble
	var out bytes.Buffer
	out.Write(pngSignature)
	writeChunk(&out, "IHDR", ihdr(w, h, bd, plan.colorType))
	if plan.colorType == ctPalette {
		writeChunk(&out, "PLTE", plan.palette)
		if plan.trns != nil {
			writeChunk(&out, "tRNS", plan.trns)
		}
	}
	for _, c := range chunks {
		writeChunk(&out, c.typ, c.data)
	}
	writeChunk(&out, "IDAT", bestData)
	writeChunk(&out, "IEND", nil)
	return out.Bytes()
}

var pngSignature = []byte{0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A}

func ihdr(w, h, bd, ct int) []byte {
	b := make([]byte, 13)
	binary.BigEndian.PutUint32(b[0:4], uint32(w))
	binary.BigEndian.PutUint32(b[4:8], uint32(h))
	b[8] = byte(bd)
	b[9] = byte(ct)
	b[10] = 0
	b[11] = 0
	b[12] = 0
	return b
}

func writeChunk(out *bytes.Buffer, typ string, data []byte) {
	var l [4]byte
	binary.BigEndian.PutUint32(l[:], uint32(len(data)))
	out.Write(l[:])
	out.WriteString(typ)
	out.Write(data)
	var c [4]byte
	binary.BigEndian.PutUint32(c[:], crc32PNG(typ, data))
	out.Write(c[:])
}

var crcTablePNG = func() [256]uint32 {
	var t [256]uint32
	for n := 0; n < 256; n++ {
		c := uint32(n)
		for k := 0; k < 8; k++ {
			if c&1 != 0 {
				c = 0xEDB88320 ^ (c >> 1)
			} else {
				c >>= 1
			}
		}
		t[n] = c
	}
	return t
}()

func crc32PNG(typ string, data []byte) uint32 {
	crc := uint32(0xFFFFFFFF)
	for i := 0; i < len(typ); i++ {
		crc = crcTablePNG[(byte(crc)^typ[i])&0xFF] ^ (crc >> 8)
	}
	for _, b := range data {
		crc = crcTablePNG[(byte(crc)^b)&0xFF] ^ (crc >> 8)
	}
	return crc ^ 0xFFFFFFFF
}

func fixedFilter(raw []byte, ft, rowBytes, bpp, h int) []byte {
	out := make([]byte, 0, len(raw))
	prev := make([]byte, rowBytes)
	for y := 0; y < h; y++ {
		cur := raw[(y)*(rowBytes+1)+1 : (y)*(rowBytes+1)+1+rowBytes]
		out = append(out, byte(ft))
		out = append(out, filterRow(ft, bpp, cur, prev)...)
		copy(prev, cur)
	}
	return out
}

func adaptiveFilter(raw []byte, rowBytes, bpp, h int) []byte {
	out := make([]byte, 0, len(raw))
	prev := make([]byte, rowBytes)
	for y := 0; y < h; y++ {
		cur := raw[(y)*(rowBytes+1)+1 : (y)*(rowBytes+1)+1+rowBytes]
		bestF, bestSum := 0, -1
		var bestRow []byte
		for ft := 0; ft <= 4; ft++ {
			fr := filterRow(ft, bpp, cur, prev)
			s := sumAbs(fr)
			if bestSum < 0 || s < bestSum {
				bestSum = s
				bestF = ft
				bestRow = fr
			}
		}
		out = append(out, byte(bestF))
		out = append(out, bestRow...)
		copy(prev, cur)
	}
	return out
}

