// chunk is a raw PNG chunk
type chunk struct {
	typ string
	data []byte
}

// ancillary PNG chunks that are preserved on re-encode
var keepChunks = map[string]bool{
	"gAMA": true, "cHRM": true, "sRGB": true, "iCCP": true, "tEXt": true,
	"zTXt": true, "iTXt": true, "pHYs": true, "sBIT": true, "bKGD": true,
	"tIME": true, "hIST": true, "sPLT": true, "oFFs": true, "pCAL": true,
	"gIFg": true, "gIFx": true, "eXIf": true, "acHP": true, "cICP": true,
	"mDCV": true, "cLLI": true,
}

// DecodePNG decodes a PNG file
func DecodePNG(data []byte) (*Image, []chunk, error) {
	d, err := pngdec.Decode(bytes.NewReader(data))
	if err != nil {
		return nil, nil, translatePNGErr(err)
	}
	var chunks []chunk
	pos := 8
	for pos+8 <= len(data) {
		ln := binary.BigEndian.Uint32(data[pos : pos+4])
		typ := string(data[pos+4 : pos+8])
		if pos+12+int(ln) > len(data) {
			break
		}
		payload := data[pos+8 : pos+8+int(ln)]
		switch typ {
		case "IHDR", "PLTE", "IDAT", "IEND", "tRNS", "fdAT", "fcTL", "acTL":
			// regenerated
		default:
			if keepChunks[typ] {
				chunks = append(chunks, chunk{typ: typ, data: append([]byte(nil), payload...)})
			}
		}
		pos += 12 + int(ln)
	}
	im, err2 := fromGoImage(d)
	if err2 != nil {
		return nil, nil, err2
	}
	return im, chunks, nil
}

func fromGoImage(d image.Image) (*Image, error) {
	b := d.Bounds()
	w, h := b.Dx(), b.Dy()
	out := New(w, h)
	switch src := d.(type) {
	case *image.Paletted:
		pal := src.Palette
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				c := pal[src.ColorIndexAt(x, y)]
				r, g, bb, a := c.RGBA()
				out.Set(x, y, uint8(r>>8), uint8(g>>8), uint8(bb>>8), uint8(a>>8))
			}
		}
	case *image.RGBA:
		for y := 0; y < h; y++ {
			copy(out.Pix[y*w*4:(y+1)*w*4], src.Pix[y*src.Stride:y*src.Stride+w*4])
		}
	case *image.NRGBA:
		for y := 0; y < h; y++ {
			copy(out.Pix[y*w*4:(y+1)*w*4], src.Pix[y*src.Stride:y*src.Stride+w*4])
		}
	case *image.Gray:
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				v := src.GrayAt(x, y).Y
				out.Set(x, y, v, v, v, 255)
			}
		}
	case *image.Gray16:
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				v := uint8(src.Gray16At(x, y).Y >> 8)
				out.Set(x, y, v, v, v, 255)
			}
		}
	case *image.RGBA64:
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				c := src.RGBA64At(x, y)
				out.Set(x, y, uint8(c.R>>8), uint8(c.G>>8), uint8(c.B>>8), uint8(c.A>>8))
			}
		}
	case *image.NRGBA64:
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				c := src.NRGBA64At(x, y)
				out.Set(x, y, uint8(c.R>>8), uint8(c.G>>8), uint8(c.B>>8), uint8(c.A>>8))
			}
		}
	case *image.CMYK:
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				c := src.CMYKAt(x, y)
				r, g, bb := cmykToRGB(c.C, c.M, c.Y, c.K)
				out.Set(x, y, r, g, bb, 255)
			}
		}
	default:
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				r, g, bb, a := d.At(x, y).RGBA()
				out.Set(x, y, uint8(r>>8), uint8(g>>8), uint8(bb>>8), uint8(a>>8))
			}
		}
	}
	return out, nil
}

func cmykToRGB(c, m, y, k uint8) (uint8, uint8, uint8) {
	r := uint8(255 - int(c)*(255-int(k))/255)
	g := uint8(255 - int(m)*(255-int(k))/255)
	b := uint8(255 - int(y)*(255-int(k))/255)
	return r, g, b
}

// translatePNGErr maps decoder errors to the messages of the original tool
