// DecodeGIF decodes an animated GIF, compositing frames
func DecodeGIF(data []byte) ([]gifFrame, int, int, error) {
	g, err := gifdec.DecodeAll(bytes.NewReader(data))
	if err != nil {
		return nil, 0, 0, errors.New("Found no usable frames to encode")
	}
