		if i > 0 {
			switch g.Disposal[i-1] {
			case 2: // restore to background
				for y := 0; y < h; y++ {
					for x := 0; x < w; x++ {
						initialized[y*w+x] = false
					}
				}
			case 3: // restore to previous
				// not tracked: fall back to background
				for y := 0; y < h; y++ {
					for x := 0; x < w; x++ {
						initialized[y*w+x] = false
					}
				}
			}
		}
		delay := 0
		if i < len(g.Delay) {
			delay = g.Delay[i]
		}
		var pal color.Palette
		if len(src.Palette) > 0 {
			pal = src.Palette
		} else if len(g.Config.ColorModel.(color.Palette)) > 0 {
			pal = g.Config.ColorModel.(color.Palette)
		}
		for y := 0; y < b.Dy(); y++ {
			for x := 0; x < b.Dx(); x++ {
				ci := src.ColorIndexAt(b.Min.X+x, b.Min.Y+y)
				var r, gg, bl, a uint8
				if pal != nil {
					cr, cg, cb, ca := pal[ci].RGBA()
					r, gg, bl, a = uint8(cr>>8), uint8(cg>>8), uint8(cb>>8), uint8(ca>>8)
				}
				px := (b.Min.Y+y)*w + (b.Min.X + x)
				if px < 0 || px >= w*h {
					continue
				}
				canvas[px*4] = r
				canvas[px*4+1] = gg
				canvas[px*4+2] = bl
				canvas[px*4+3] = a
				initialized[px] = true
			}
		}
		full := New(w, h)
		copy(full.Pix, canvas)
		for p := range initialized {
			if !initialized[p] {
				full.Pix[p*4+3] = 0
			}
		}
		out = append(out, gifFrame{im: full, delay: delay})
	}
	if len(out) == 0 {
		return nil, 0, 0, errors.New("Found no usable frames to encode")
	}
	return out, w, h, nil
}

// DecodeGIFSingle decodes only the first frame (used for still conversions)
func DecodeGIFSingle(data []byte) (*Image, error) {
	d, err := gifdec.Decode(bytes.NewReader(data))
	if err != nil {
		return nil, errors.New("Found no usable frames to encode")
	}
	return fromGoImage(d)
}

// EncodeGIF writes an animated GIF
func EncodeGIF(frames []gifFrame, w, h int, lossy bool, quality int) []byte {
	var out bytes.Buffer
	out.WriteString("GIF89a")
	put16(&out, w)
	put16(&out, h)
	out.WriteByte(0x70) // no global color table, color resolution 7
	out.WriteByte(0)
	out.WriteByte(0)
	// NETSCAPE loop extension
	out.WriteByte(0x21)
	out.WriteByte(0xFF)
	out.WriteByte(0x0B)
	out.WriteString("NETSCAPE2.0")
	out.WriteByte(0x03)
	out.WriteByte(0x01)
	put16(&out, 0)
	out.WriteByte(0)
	var prev *Image
	for i := range frames {
		f := &frames[i]
		cur := f.im
		left, top := 0, 0
		cw, ch := cur.W, cur.H
		// transparent palette entry used for delta frames
		useTrans := false
		if lossy && prev != nil {
			// compute the changed region
			minx, miny, maxx, maxy := cur.W, cur.H, -1, -1
			for y := 0; y < cur.H; y++ {
				for x := 0; x < cur.W; x++ {
					j := (y*cur.W + x) * 4
					if !pixEq(cur.Pix[j:j+4], prev.Pix[j:j+4]) {
						if x < minx {
							minx = x
						}
						if x > maxx {
							maxx = x
						}
						if y < miny {
							miny = y
						}
						if y > maxy {
							maxy = y
						}
					}
				}
			}
			if maxx >= minx {
				left, top = minx, miny
				cw, ch = maxx-minx+1, maxy-miny+1
				sub := New(cw, ch)
				for y := 0; y < ch; y++ {
					for x := 0; x < cw; x++ {
						j := ((top+y)*cur.W + left + x) * 4
						if pixEq(cur.Pix[j:j+4], prev.Pix[j:j+4]) {
							sub.Set(x, y, 0, 0, 0, 0)
						} else {
							sub.Pix[(y*cw+x)*4+0] = cur.Pix[j]
							sub.Pix[(y*cw+x)*4+1] = cur.Pix[j+1]
							sub.Pix[(y*cw+x)*4+2] = cur.Pix[j+2]
							sub.Pix[(y*cw+x)*4+3] = cur.Pix[j+3]
						}
					}
				}
				cur = sub
				useTrans = true
			} else {
				// nothing changed: write a 1x1 transparent frame
				cw, ch = 1, 1
				sub := New(1, 1)
				sub.Pix[3] = 0
				cur = sub
				useTrans = true
			}
		}
		// graphic control extension
		disposal := 0
		if useTrans {
			disposal = 1
		}
		out.WriteByte(0x21)
		out.WriteByte(0xF9)
		out.WriteByte(0x04)
		out.WriteByte(byte(disposal << 2))
		put16(&out, f.delay)
		out.WriteByte(0)
		out.WriteByte(0)
		// image descriptor + palette
		pal, indices, transIdx := quantizeFrame(cur, quality, lossy)
		flags := byte(0x80) | byte(bitsFor(len(pal))-1)
		if transIdx >= 0 {
			flags |= 0x01
		}
		out.WriteByte(0x2C)
		put16(&out, left)
		put16(&out, top)
		put16(&out, cw)
		put16(&out, ch)
		out.WriteByte(flags)
		for _, e := range pal {
			out.WriteByte(e[0])
			out.WriteByte(e[1])
			out.WriteByte(e[2])
		}
		if transIdx >= 0 {
			out.WriteByte(byte(transIdx))
		}
		lzwEncode(&out, indices, cw, ch, bitsFor(len(pal)))
		prev = f.im
	}
	out.WriteByte(0x3B)
	return out.Bytes()
}

func pixEq(a, b []uint8) bool {
	return a[0] == b[0] && a[1] == b[1] && a[2] == b[2] && a[3] == b[3]
}

func bitsFor(n int) int {
	b := 1
	for (1 << uint(b)) < n {
		b++
	}
	if b < 1 {
		b = 1
	}
	return b
}

func put16(out *bytes.Buffer, v int) {
	out.WriteByte(byte(v & 0xFF))
	out.WriteByte(byte((v >> 8) & 0xFF))
}

// quantizeFrame builds a palette and the index data for a frame
func quantizeFrame(im *Image, quality int, lossy bool) ([][3]uint8, []byte, int) {
	w, h := im.W, im.H
	n := w * h
	maxColors := 256
	if lossy && quality < 100 {
		maxColors = 256
		if quality <= 20 {
			maxColors = 16
		} else if quality <= 50 {
			maxColors = 64
		}
	}
	pal, indices := quantize(im, maxColors)
	var trns int = -1
	hasTrans := false
	for i := 0; i < n; i++ {
		if im.Pix[i*4+3] != 255 {
			hasTrans = true
			break
		}
	}
	out := make([][3]uint8, 0, len(pal))
	for _, e := range pal {
		out = append(out, [3]uint8{e[0], e[1], e[2]})
	}
	if hasTrans {
		// append a transparent entry and remap transparent pixels
		trns = len(out)
		out = append(out, [3]uint8{0, 0, 0})
		for i := 0; i < n; i++ {
			if im.Pix[i*4+3] == 0 {
				indices[i] = byte(trns)
			}
		}
		// pad the palette to a power of two
	}
	for len(out) < (1 << uint(bitsFor(len(out)))) {
		out = append(out, [3]uint8{0, 0, 0})
	}
	return out, indices, trns
}

// lzwEncode writes a frame's LZW compressed index data
func lzwEncode(out *bytes.Buffer, indices []byte, w, h, minCodeSize int) {
	if len(indices) == 0 {
		out.WriteByte(0)
		return
	}
	clearCode := 1 << uint(minCodeSize)
	eoi := clearCode + 1
	codeSize := minCodeSize + 1
	dict := map[string]int{}
	nextCode := eoi + 1
	bw := &bitWriter{}
	emit := func(code int) {
		bw.put(uint32(code), codeSize)
	}
	resetDict := func() {
		dict = map[string]int{}
		for i := 0; i < clearCode; i++ {
			dict[string([]byte{byte(i)})] = i
		}
		nextCode = eoi + 1
		codeSize = minCodeSize + 1
	}
	resetDict()
	emit(clearCode)
