package img

import (
	"bytes"
	"encoding/binary"
)

// csError is an error carrying the message and code of the original library
type csError struct {
	msg  string
	code int
	codes []int
}

func (e *csError) Error() string {
	s := e.msg
	for _, c := range e.codes {
		s += " [" + itoa(c) + "]"
	}
	return s
}

func itoa(v int) string {
	if v == 0 {
		return "0"
	}
	neg := v < 0
	if neg {
		v = -v
	}
	var b [20]byte
	i := len(b)
	for v > 0 {
		i--
		b[i] = byte('0' + v%10)
		v /= 10
	}
	if neg {
		i--
		b[i] = '-'
	}
	return string(b[i:])
}

// DecodeJPEG decodes a JPEG file and returns the image plus its metadata markers
func DecodeJPEG(data []byte) (*Image, []jpegMarker, error) {
	img, err := jpegDecode(data)
	if err != nil {
		return nil, nil, &csError{msg: "Internal JPEG error: 51", code: 20104}
	}
	var markers []jpegMarker
	i := 2
	for i+4 <= len(data) {
		if data[i] != 0xFF {
			break
		}
		m := data[i+1]
		if m == 0xFF {
			i++
			continue
		}
		if m == 0xD8 {
			i += 2
			continue
		}
		if m == 0xD9 {
			break
		}
		if m == 0x01 || (m >= 0xD0 && m <= 0xD7) {
			i += 2
			continue
		}
		seg := int(binary.BigEndian.Uint16(data[i+2 : i+4]))
		if seg < 2 || i+2+seg > len(data) {
			break
		}
		payload := data[i+4 : i+2+seg]
		if m >= 0xE0 && m <= 0xEF {
			markers = append(markers, jpegMarker{marker: m, data: append([]byte(nil), payload...)})
		} else if m == 0xFE {
			markers = append(markers, jpegMarker{marker: m, data: append([]byte(nil), payload...)})
		}
		i += 2 + seg
	}
	return img, markers, nil
}

type jpegMarker struct {
	marker byte
	data   []byte
}

// jpegDecode decodes JPEG data using the standard library
func jpegDecode(data []byte) (*Image, error) {
	d, err := jpegDec(bytes.NewReader(data))
	if err != nil {
		return nil, err
	}
	return fromGoImage(d)
}
