package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	"github.com/caesiumclt/src/img"
)

// process handles a single file
func process(cfg *config, t *task) result {
	r := result{task: t}
	// ensure the output directory exists
	if !cfg.sameFolder {
		dir := filepath.Dir(t.dst)
		if _, err := os.Stat(dir); err != nil {
			if err := os.MkdirAll(dir, 0o755); err != nil {
				r.status = stError
				r.reason = "Error creating output file"
				return r
			}
		}
	}
	// overwrite policy
	if !cfg.dryRun {
		if st, err := os.Stat(t.dst); err == nil && !st.IsDir() {
			switch cfg.overwrite {
			case "never":
				r.status = stSkipped
				r.reason = "File already exists, skipped due overwrite policy"
				return r
			case "bigger":
				if t.size >= uint64(st.Size()) {
					r.status = stSkipped
					r.reason = "File already exists, skipped due overwrite policy"
					return r
				}
			}
		}
	}
	if cfg.dryRun {
		r.status = stSuccess
		r.newSize = t.size
		return r
	}
	data, err := os.ReadFile(t.src)
	if err != nil {
		r.status = stError
		r.reason = "Error compressing file: " + err.Error()
		return r
	}
	out, newSize, cerr := compress(cfg, t, data)
	if cerr != nil {
		r.status = stError
		r.reason = "Error compressing file: " + cerr.Error()
		return r
	}
	// min savings
	if cfg.hasMinSavings {
		savings := int64(t.size) - int64(newSize)
		if savings < 0 {
			savings = 0
		}
		if cfg.minSavings.isPercent {
			pct := float64(savings) / float64(t.size) * 100
			if !(pct > cfg.minSavings.percent) {
				r.status = stSkipped
				r.reason = "Insufficient savings: " + strconv.FormatFloat(pct, 'f', 2, 64) + "% < " +
					strconv.FormatFloat(cfg.minSavings.percent, 'f', 2, 64) + "%, skipped"
				return r
			}
		} else {
			if !(uint64(savings) > cfg.minSavings.bytes) {
				r.status = stSkipped
				r.reason = "Insufficient savings: " + formatSize(uint64(savings)) + " < " +
					cfg.minSavings.display(t.size) + ", skipped"
				return r
			}
		}
	}
	if err := os.WriteFile(t.dst, out, 0o644); err != nil {
		r.status = stError
		r.reason = "Error creating output file"
		return r
	}
	if cfg.keepDates {
		if st, err := os.Stat(t.src); err == nil {
			os.Chtimes(t.dst, st.ModTime(), st.ModTime())
		}
	}
	r.status = stSuccess
	r.newSize = newSize
	return r
}

// compress decodes, resizes and encodes a file
func compress(cfg *config, t *task, data []byte) ([]byte, uint64, error) {
	var im *img.Image
	var meta []byte
	switch t.format {
	case fmtJpeg:
		i, markers, err := img.DecodeJPEG(data)
		if err != nil {
			return nil, 0, err
		}
		im = i
		meta = jpegMetadata(cfg, markers)
	case fmtPng:
		i, chunks, err := img.DecodePNG(data)
		if err != nil {
			return nil, 0, &csError{msg: "Invalid data found; unable to read PNG file", code: 20210}
		}
		im = i
		meta = pngChunks(chunks)
	case fmtGif:
		frames, w, h, err := img.DecodeGIF(data)
		if err != nil {
			return nil, 0, err
		}
		out, err2 := encodeGif(cfg, frames, w, h, len(frames) > 1)
		return out, uint64(len(out)), err2
	case fmtWebp:
		i, err := img.DecodeWebP(data)
		if err != nil {
			return nil, 0, &csError{msg: "null_decoder", code: 20304}
		}
		im = i
	}
	if im == nil {
		return nil, 0, errors.New("unsupported")
	}
	// resize
	tw, th := targetSize(cfg, im.W, im.H)
	if tw != im.W || th != im.H {
		im = img.Resize(im, tw, th)
	}
	out, err := encodeImage(cfg, t.format, im, meta)
	if err != nil {
		return nil, 0, err
	}
	return out, uint64(len(out)), nil
}

// targetSize computes the output dimensions honouring the resize options and
// the EXIF orientation (which the original handles by swapping the axes).
func targetSize(cfg *config, w, h int) (int, int) {
	tw, th := w, h
	rotated := orientationRotated(cfg, w, h)
	// display dimensions
	dw, dh := w, h
	if rotated {
		dw, dh = h, w
	}
	switch {
	case cfg.hasWidth && cfg.hasHeight:
		tw, th = int(cfg.width), int(cfg.height)
	case cfg.hasWidth:
		tw = int(cfg.width)
		th = round(float64(tw) * float64(dh) / float64(dw))
		if th < 1 {
			th = 1
		}
	case cfg.hasHeight:
		th = int(cfg.height)
		tw = round(float64(th) * float64(dw) / float64(dh))
		if tw < 1 {
			tw = 1
		}
	case cfg.hasLongEdge || cfg.hasShortEdge:
		// the original decides which edge is long using the physical dimensions
		physicalLandscape := w >= h
		if cfg.hasLongEdge {
			if physicalLandscape {
				tw = int(cfg.longEdge)
				th = round(float64(tw) * float64(dh) / float64(dw))
			} else {
				th = int(cfg.longEdge)
				tw = round(float64(th) * float64(dw) / float64(dh))
			}
		} else {
			if physicalLandscape {
				th = int(cfg.shortEdge)
				tw = round(float64(th) * float64(dw) / float64(dh))
			} else {
				tw = int(cfg.shortEdge)
				th = round(float64(tw) * float64(dh) / float64(dw))
			}
		}
		if tw < 1 {
			tw = 1
		}
		if th < 1 {
			th = 1
		}
	}
	if rotated {
		tw, th = th, tw
	}
	if cfg.noUpscale {
		if rotated {
			// compare against the display size
			if tw > dh && th > dw {
				tw, th = h, w
			}
		} else if tw > w || th > h {
			tw, th = w, h
		}
	}
	return tw, th
}

func round(v float64) int {
	if v < 0 {
		return -int(-v + 0.5)
	}
	return int(v + 0.5)
}

// encodeImage encodes the image in the requested output format
func encodeImage(cfg *config, f format, im *img.Image, meta []byte) ([]byte, error) {
	target := cfg.format
	if target == "original" {
		switch f {
		case fmtJpeg:
			target = "jpeg"
		case fmtPng:
			target = "png"
		case fmtGif:
			target = "gif"
		case fmtWebp:
			target = "webp"
		}
	}
	switch target {
	case "jpeg":
		q := jpegQuality(cfg)
		var quant [2][64]int
		if cfg.lossless {
			quant = img.QuantTablesForQualityStd(50)
		} else {
			quant = img.QuantTablesForQuality(q)
		}
		opts := img.JpegEncOptions{
			Quality:     q,
			Subsampling: cfg.subsampling,
			Progressive: !cfg.jpegBaseline,
			Quant:       quant,
			Exif:        meta,
		}
		return img.EncodeJPEG(im, opts), nil
	case "png":
		if cfg.lossless {
			return img.EncodePNG(im, cfg.pngOptLevel, cfg.zopfli, img.DecodeChunks(meta)), nil
		}
		return img.EncodePNGLossy(im, qFor(cfg), cfg.pngOptLevel, cfg.zopfli), nil
	case "gif":
		return img.EncodeGIFSingle(im, cfg.lossless, qFor(cfg))
	case "webp":
		return img.EncodeWebP(im, float64(qFor(cfg)), cfg.lossless)
	case "tiff":
		return img.EncodeTIFF(im), nil
	}
	return nil, errors.New("unsupported format")
}

func qFor(cfg *config) int {
	if cfg.lossless {
		return 100
	}
	return int(cfg.quality)
}

func jpegQuality(cfg *config) int {
	if cfg.lossless {
		return 100
	}
	return int(cfg.quality)
}

// jpegMetadata collects the metadata markers to preserve
func jpegMetadata(cfg *config, markers []img.JpegMarker) []byte {
	if !cfg.exif {
		return nil
	}
	var out []byte
	for _, m := range markers {
		if m.Marker == 0xE2 && cfg.stripICC {
			continue
		}
		out = append(out, 0xFF, m.Marker)
		out = append(out, byte(len(m.Data)+2)>>8, byte((len(m.Data)+2)&0xFF))
		out = append(out, m.Data...)
	}
	return out
}

func pngChunks(chunks []img.Chunk) []byte {
	var out []byte
	for _, c := range chunks {
		out = append(out, 0, 0, 0, 0)
		out = append(out, c.Typ...)
		out = append(out, c.Data...)
		out = append(out, 0, 0, 0, 0)
	}
	return out
}

func formatSize(n uint64) string { return sizeFormat(n) }

var _ = time.Time{}
var _ = strings.TrimSpace
var _ = fmt.Sprintf
GOEOF
echo ok"}

