	return img.EncodeGIF(frames, w, h, lossy, qFor(cfg)), nil
}

// targetSize computes the output dimensions
func targetSize(cfg *config, w, h int, t *task) (int, int) {
	tw, th := w, h
	rotated := taskRotated(t)
	dw, dh := w, h
	if rotated {
		dw, dh = h, w
	}
	switch {
	case cfg.hasWidth && cfg.hasHeight:
		tw, th = int(cfg.width), int(cfg.height)
	case cfg.hasWidth:
		tw = int(cfg.width)
		th = round(float64(tw) * float64(dh) / float64(dw))
		if th < 1 {
			th = 1
		}
	case cfg.hasHeight:
		th = int(cfg.height)
		tw = round(float64(th) * float64(dw) / float64(dh))
		if tw < 1 {
			tw = 1
		}
	case cfg.hasLongEdge || cfg.hasShortEdge:
		physicalLandscape := w >= h
		if cfg.hasLongEdge {
			if physicalLandscape {
				tw = int(cfg.longEdge)
				th = round(float64(tw) * float64(dh) / float64(dw))
			} else {
				th = int(cfg.longEdge)
				tw = round(float64(th) * float64(dw) / float64(dh))
			}
		} else {
			if physicalLandscape {
				th = int(cfg.shortEdge)
				tw = round(float64(th) * float64(dw) / float64(dh))
			} else {
				tw = int(cfg.shortEdge)
				th = round(float64(tw) * float64(dh) / float64(dw))
			}
		}
		if tw < 1 {
			tw = 1
		}
		if th < 1 {
			th = 1
		}
	}
	if rotated {
		tw, th = th, tw
	}
	if cfg.noUpscale {
		if tw > dw || th > dh {
			tw, th = w, h
		}
	}
	return tw, th
}

func round(v float64) int {
	if v < 0 {
		return -int(-v + 0.5)
	}
	return int(v + 0.5)
}

// encodeImage encodes the image in the requested output format
func encodeImage(cfg *config, f format, im *img.Image, m *meta) ([]byte, error) {
	target := cfg.format
	if target == "original" {
		switch f {
		case fmtJpeg:
			target = "jpeg"
		case fmtPng:
			target = "png"
		case fmtGif:
			target = "gif"
		case fmtWebp:
			target = "webp"
		}
	}
	switch target {
	case "jpeg":
		var quant [2][64]int
		if cfg.lossless {
			quant = img.QuantTablesForQualityStd(50)
		} else {
			quant = img.QuantTablesForQuality(int(cfg.quality))
		}
		opts := img.JpegEncOptions{
			Quality:     int(cfg.quality),
			Subsampling: cfg.subsampling,
			Progressive: !cfg.jpegBaseline,
			Quant:       quant,
			Exif:        jpegMetadata(cfg, m.jmarkers),
		}
		return img.EncodeJPEG(im, opts), nil
	case "png":
		if cfg.lossless {
			return img.EncodePNG(im, cfg.pngOptLevel, cfg.zopfli, m.chunks), nil
		}
		return img.EncodePNGLossy(im, qFor(cfg), cfg.pngOptLevel, cfg.zopfli), nil
	case "gif":
		return img.EncodeGIFSingle(im, cfg.lossless, qFor(cfg))
	case "webp":
		return img.EncodeWebP(im, float64(qFor(cfg)), cfg.lossless)
	case "tiff":
		return img.EncodeTIFF(im), nil
	}
	return nil, errors.New("unsupported format")
}

func qFor(cfg *config) int {
	if cfg.lossless {
		return 100
	}
	return int(cfg.quality)
}

// jpegMetadata collects the metadata markers to preserve
func jpegMetadata(cfg *config, markers []img.JpegMarker) []byte {
	if !cfg.exif {
		return nil
	}
	var out []byte
	for _, mk := range markers {
		if mk.Marker == 0xE2 && cfg.stripICC {
			continue
		}
		out = append(out, 0xFF, mk.Marker)
		l := len(mk.Data) + 2
		out = append(out, byte(l>>8), byte(l&0xFF))
		out = append(out, mk.Data...)
	}
	return out
}

func formatSize(n uint64) string { return sizeFormat(n) }
