python3 - <<'PY'
s=open('src/img/png.go').read()
s+='''

// EncodePNGOpt encodes with explicit level/strategy (test helper)
func EncodePNGOpt(im *Image, optLevel int, filter int, level int, strategy int, chunks []Chunk) []byte {
	plan := planPNG(im, false, 0)
	return encodePNGPlanOpt(plan, filter, level, strategy, chunks)
}

func encodePNGPlanOpt(plan *pngPlan, filter, level, strategy int, chunks []Chunk) []byte {
	w, h := plan.width, plan.height
	bd := plan.bitDepth
	bpp := plan.bpp
	rowBytes := (w*bpp*bd + 7) / 8
	raw := make([]byte, 0, h*(rowBytes+1))
	for y := 0; y < h; y++ {
		raw = append(raw, 0)
		raw = append(raw, plan.raw[y*rowBytes:(y+1)*rowBytes]...)
	}
	var filtered []byte
	if filter == -1 {
		filtered = adaptiveFilter(raw, rowBytes, bpp, h)
	} else {
		filtered = fixedFilter(raw, filter, rowBytes, bpp, h)
	}
	data, ok := deflateRaw(filtered, level, strategy)
	if !ok {
		return nil
	}
	var out bytes.Buffer
	out.Write(pngSignature)
	writeChunk(&out, "IHDR", ihdr(w, h, bd, plan.colorType))
	if plan.colorType == ctPalette {
		writeChunk(&out, "PLTE", plan.palette)
		if plan.trns != nil {
			writeChunk(&out, "tRNS", plan.trns)
		}
	}
	for _, c := range chunks {
		writeChunk(&out, c.Typ, c.Data)
	}
	writeChunk(&out, "IDAT", data)
	writeChunk(&out, "IEND", nil)
	return out.Bytes()
}
'''
open('src/img/png.go','w').write(s)
