./compile.sh && cd /tmp/t && cat > /tmp/ztest/main.go 2>/dev/null; mkdir -p /tmp/ztest && cp /tmp/ztest.go /tmp/ztest/main.go && cp -r /workspace/src /tmp/ztest/src 2>/dev/null; cd /tmp/ztest && cp /workspace/go.mod . && go build -o zt . 2>&1|head -3 && ./zt /tmp/t/in/p0.png"}

