def pnginfo(p):
    d=open(p,'rb').read()
    if len(d)<33: return None
    w,h=struct.unpack('>II',d[16:24]); bd,ct=d[24],d[25]
    return ('png',w,h,bd,ct,len(d))
def jpeginfo(p):
    d=open(p,'rb').read()
    i=2
    while i+4<len(d):
        if d[i]!=0xFF: return None
        m=d[i+1]
        if m==0xFF: i+=1; continue
        seg=struct.unpack('>H',d[i+2:i+4])[0]
        if 0xC0<=m<=0xCF and m not in (0xC4,0xC8,0xCC):
            h,w=struct.unpack('>HH',d[i+5:i+9]); nc=d[i+9]
            return ('jpg',w,h,nc,m,len(d))
        i+=2+seg
    return None
def webpinfo(p):
    d=open(p,'rb').read()
    if len(d)<30: return None
    tag=d[12:16]
    if tag==b'VP8 ':
        w=struct.unpack('<H',d[26:28])[0]&0x3fff; h=struct.unpack('<H',d[28:30])[0]&0x3fff
    elif tag==b'VP8L':
        b=d[21:26]; w=1+b[1]+((b[2]&0x3f)<<8); h=1+(b[2]>>6)+((b[3]&0xf)<<2)+((b[4]&3)<<10)
    elif tag==b'VP8X':
        w=1+d[24]+(d[25]<<8)+(d[26]<<16); h=1+d[27]+(d[28]<<8)+(d[29]<<16)
    else: return None
    return ('webp',w,h,tag.decode(),len(d))
def gifinfo(p):
    d=open(p,'rb').read(); w,h=struct.unpack('<HH',d[6:10]); return ('gif',w,h,len(d))
def tiffinfo(p):
    d=open(p,'rb').read(); off=struct.unpack('<I',d[4:8])[0]
    tags={}; n=struct.unpack('<H',d[off:off+2])[0]
    for i in range(n):
        tag,typ,cnt,val=struct.unpack('<HHII',d[off+2+i*12:off+14+i*12]); tags[tag]=(typ,cnt,val)
    return ('tiff',tags.get(256,(0,0,0))[2],tags.get(257,(0,0,0))[2],len(d))
def info(p):
    d=open(p,'rb').read(4)
    if d[:2]==b'\xff\xd8': return jpeginfo(p)
    if d[:4]==b'\x89PNG': return pnginfo(p)
    if d[:4]==b'RIFF': return webpinfo(p)
    if d[:3]==b'GIF': return gifinfo(p)
    if d[:2] in (b'II',b'MM'):
        try: return tiffinfo(p)
        except Exception: return None
    return None
