 ("jpeg q sweep (oqt)", ["--format","jpeg"], "oqt", "p0q%d.jpg", [(q,"--suffix","q%d"%q,"-o","REFOUT") for q in range(0,101,10)]),
]
def cmpfiles(name, refdir, mydir, outname):
    a=REF+"/"+refdir+"/"+outname; b=mydir+"/"+outname
    ia=info(a) if os.path.exists(a) else None
    ib=info(b) if os.path.exists(b) else None
    if ia is None and ib is None: return "MISSING"
    if (ia is None)!=(ib is None): return "MISSING-MISMATCH %s %s"%(ia,ib)
    if ia[:4]!=ib[:4]: return "META %s vs %s"%(ia,ib)
    r=ib[4]/ia[4] if ia[4] else 0
    flag = "" if (0.7<=r<=1.4) else "  <<< SIZE"
    return "size %d -> %d (%.2f)%s"%(ia[4],ib[4],r,flag)
bad=0; tot=0
def run(name, args, refdir, suffix, files):
