// exifRotated returns true when the EXIF orientation implies a 90/270 rotation
func exifRotated(d []byte, f format) bool {
	if f != fmtJpeg {
		return false
	}
	ori, ok := jpegOrientation(d)
	if !ok {
		return false
	}
	return ori >= 5 && ori <= 8
}

// jpegOrientation extracts the EXIF orientation tag from a JPEG file
func jpegOrientation(d []byte) (int, bool) {
	i := 2
	for i+4 <= len(d) {
		if d[i] != 0xFF {
			return 0, false
		}
		m := d[i+1]
		if m == 0xFF {
			i++
			continue
		}
		if m == 0xD8 {
			i += 2
			continue
		}
		if m == 0xDA || m == 0xD9 {
			return 0, false
		}
		if m == 0x01 || (m >= 0xD0 && m <= 0xD7) {
			i += 2
			continue
		}
		seg := int(binary.BigEndian.Uint16(d[i+2 : i+4]))
		if seg < 2 || i+2+seg > len(d) {
			return 0, false
		}
		payload := d[i+4 : i+2+seg]
		if m == 0xE1 && len(payload) > 6 && string(payload[:6]) == "Exif\\x00\\x00" {
			if ori, ok := tiffOrientation(payload[6:]); ok {
				return ori, true
			}
		}
		i += 2 + seg
	}
	return 0, false
}

// tiffOrientation reads the orientation tag from an EXIF TIFF structure
func tiffOrientation(tiff []byte) (int, bool) {
	if len(tiff) < 8 {
		return 0, false
	}
	le := tiff[0] == 'I' && tiff[1] == 'I'
	if !le && !(tiff[0] == 'M' && tiff[1] == 'M') {
		return 0, false
	}
	u16 := func(off int) int {
		if le {
			return int(binary.LittleEndian.Uint16(tiff[off:]))
		}
		return int(binary.BigEndian.Uint16(tiff[off:]))
	}
	u32 := func(off int) int {
		if le {
			return int(binary.LittleEndian.Uint32(tiff[off:]))
		}
		return int(binary.BigEndian.Uint32(tiff[off:]))
	}
	off := u32(4)
	if off+2 > len(tiff) {
		return 0, false
	}
	n := u16(off)
	for k := 0; k < n; k++ {
		e := off + 2 + k*12
		if e+12 > len(tiff) {
			return 0, false
		}
		tag := u16(e)
		if tag != 0x0112 {
			continue
		}
		typ := u16(e + 2)
		if typ != 3 && typ != 4 {
			return 0, false
		}
		v := u16(e + 8)
		return v, true
	}
	return 0, false
}
