def dims(p):
    d=open(p,'rb').read(64)
    if d[:2]==b'\xff\xd8':
        i=2
        while i+4<len(d):
            if d[i]!=0xFF: return None
            m=d[i+1]
            if m==0xFF: i+=1; continue
            seg=struct.unpack('>H',d[i+2:i+4])[0]
            if 0xC0<=m<=0xCF and m not in (0xC4,0xC8,0xCC):
                h,w=struct.unpack('>HH',d[i+5:i+9]); return ('jpg',w,h)
            i+=2+seg
        return None
    if d[:4]==b'\x89PNG':
        w,h=struct.unpack('>II',open(p,'rb').read()[16:24]); bd,ct=open(p,'rb').read()[24],open(p,'rb').read()[25]
        return ('png',w,h,bd,ct)
    if d[:4]==b'RIFF':
        d=open(p,'rb').read()
        tag=d[12:16]
        if tag==b'VP8 ': return ('webp',struct.unpack('<H',d[26:28])[0]&0x3fff,struct.unpack('<H',d[28:30])[0]&0x3fff)
        if tag==b'VP8L':
            b=d[21:26]; return ('webp',1+b[1]+((b[2]&0x3f)<<8),1+(b[2]>>6)+((b[3]&0xf)<<2)+((b[4]&3)<<10))
        if tag==b'VP8X': return ('webp',1+d[24]+(d[25]<<8)+(d[26]<<16),1+d[27]+(d[28]<<8)+(d[29]<<16))
    if d[:3]==b'GIF':
        w,h=struct.unpack('<HH',open(p,'rb').read()[6:10]); return ('gif',w,h)
    if d[:2] in (b'II',b'MM'):
        dd=open(p,'rb').read(); off=struct.unpack('<I',dd[4:8])[0]
        tags={}
        n=struct.unpack('<H',dd[off:off+2])[0]
        for i in range(n):
            tag,typ,cnt,val=struct.unpack('<HHII',dd[off+2+i*12:off+14+i*12]); tags[tag]=val
        return ('tiff',tags.get(256),tags.get(257))
    return None
