        msg.append("%s:%d->%d(%.2f)%s"%(f,sa,sb,ratio,mark))
    line=" | ".join(msg)
    if any("MISMATCH" in m or "DIMS" in m or "<<<" in m for m in msg): bad+=1
    print("%-4s %-26s %s"%("DIFF" if any("MISMATCH" in m or "DIMS" in m or "<<<" in m for m in msg) else "ok", name, line))
